// Additive, finite companion for the existing clean native finance adapter.
// Old manifests/bodies are retained and verified, not rewritten in-place.
import {moduleHash} from './stage4-copy-sql.mjs';
import {CLEAN_FINANCE_FX_CASES} from '../../apps/api/src/services/cleanFinanceRehearsalModel.mjs';
import {readFileSync} from 'node:fs';

function cashFinishDefinition(){return `CREATE PROCEDURE dbo.usp_clean_finance_b4_cash_finish @request_id uniqueidentifier WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;${CLEAN_TARGET_SQL}${cashLoad}
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' OR @request<>@request_id OR @op NOT IN(N'cash_open',N'cash_close',N'cash_transfer',N'cash_expense') OR @sid IS NULL ${deny}
 IF HASHBYTES('SHA2_256',${cashProtected})<>(SELECT protected_hash FROM dbo.${cashIntent} WHERE session_id=@@SPID) ${deny}
 DECLARE @transfers int=0,@adjustments int=0,@expenses int=CASE WHEN @op=N'cash_expense' THEN 1 ELSE 0 END;
 IF @op=N'cash_transfer' SET @transfers=1;
 IF @op IN(N'cash_open',N'cash_close') BEGIN
 SELECT @transfers=COUNT(*) FROM OPENJSON(@payload,'$.counts') c WHERE CASE WHEN @op=N'cash_open' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(c.value,'$.openingTransfer')) ELSE TRY_CONVERT(decimal(18,4),JSON_VALUE(c.value,'$.physicalClosing'))-TRY_CONVERT(decimal(18,4),JSON_VALUE(c.value,'$.carryForward')) END>0;
 SELECT @adjustments=COUNT(*) FROM OPENJSON(@payload,'$.counts') c JOIN OPENJSON(@balances) WITH(id bigint,current_balance decimal(18,4)) b ON b.id=CASE c.[key] WHEN N'TRY' THEN 2 WHEN N'USD' THEN 3 WHEN N'EUR' THEN 4 ELSE -1 END WHERE b.current_balance<>TRY_CONVERT(decimal(18,4),JSON_VALUE(c.value,CASE WHEN @op=N'cash_open' THEN '$.physicalOpening' ELSE '$.physicalClosing' END));
 END;
 IF(SELECT COUNT(*) FROM dbo.cash_transfers)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.transfer_count'))+@transfers OR(SELECT COUNT(*) FROM dbo.cash_adjustments)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.adjustment_count'))+@adjustments OR(SELECT COUNT(*) FROM dbo.cash_expenses)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.expense_count'))+@expenses OR(SELECT COUNT(*) FROM dbo.finance_account_movements)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.finance_count'))+2*@transfers+@adjustments+@expenses OR(SELECT COUNT(*) FROM dbo.cash_sessions)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.session_count'))+CASE WHEN @op=N'cash_open' THEN 1 ELSE 0 END OR(SELECT COUNT(*) FROM dbo.cash_session_counts)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.count_count'))+CASE WHEN @op=N'cash_open' THEN 3 ELSE 0 END OR(SELECT COUNT(*) FROM dbo.audit_logs)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.audit_count'))+1 OR(SELECT COUNT(*) FROM dbo.work_trade_requests)<>TRY_CONVERT(int,JSON_VALUE(@before,'$.request_count'))+1 ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.cash_sessions WHERE id=@sid AND drawer_id=1 AND business_date=CONVERT(date,'20261022',112) AND session_status=CASE WHEN @op=N'cash_close' THEN N'closed' ELSE N'open' END) OR(SELECT COUNT(*) FROM dbo.cash_session_counts WHERE session_id=@sid)<>3 ${deny}
 IF EXISTS(SELECT 1 FROM(VALUES(N'TRY',2,5),(N'USD',3,6),(N'EUR',4,7)) c(currency,drawer,main) JOIN dbo.finance_accounts d ON d.id=c.drawer JOIN dbo.finance_accounts m ON m.id=c.main JOIN OPENJSON(@balances) WITH(id bigint,current_balance decimal(18,4)) bd ON bd.id=c.drawer JOIN OPENJSON(@balances) WITH(id bigint,current_balance decimal(18,4)) bm ON bm.id=c.main WHERE d.current_balance<>CASE @op WHEN N'cash_open' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+c.currency+N'.physicalOpening'))+TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+c.currency+N'.openingTransfer')) WHEN N'cash_close' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+c.currency+N'.carryForward')) ELSE bd.current_balance+CASE WHEN c.currency<>JSON_VALUE(@payload,'$.currency') THEN 0 WHEN @op=N'cash_expense' OR JSON_VALUE(@payload,'$.direction')=N'drawer_to_main' THEN -TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amount')) ELSE TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amount')) END END OR m.current_balance<>bm.current_balance+CASE @op WHEN N'cash_open' THEN -TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+c.currency+N'.openingTransfer')) WHEN N'cash_close' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+c.currency+N'.physicalClosing'))-TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+c.currency+N'.carryForward')) WHEN N'cash_transfer' THEN CASE WHEN c.currency<>JSON_VALUE(@payload,'$.currency') THEN 0 WHEN JSON_VALUE(@payload,'$.direction')=N'main_to_drawer' THEN -TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amount')) ELSE TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amount')) END ELSE 0 END) ${deny}
 DECLARE @response nvarchar(max);SELECT @response=response_json FROM dbo.work_trade_requests WHERE request_id=@request AND actor_id=@actor AND operation=@op AND payload_hash=@payloadHash AND payload_json=@payload;
 IF @response IS NULL OR ISNULL(LOWER(JSON_VALUE(@response,'$.requestId')),N'')<>LOWER(CONVERT(nvarchar(36),@request)) ${deny}
 EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_cash_ready;
 DELETE dbo.${cashIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();
 DECLARE @hash char(64)=@payloadHash;${witness('verified')} END;`;}

function cashGuardDefinition(){return `CREATE PROCEDURE dbo.usp_clean_finance_b4_cash_guard @table_name sysname,@inserted nvarchar(max),@deleted nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}${cashLoad}
 IF ISJSON(@inserted)<>1 OR ISJSON(@deleted)<>1 OR(SELECT COUNT(*) FROM OPENJSON(@inserted))<>1 OR(SELECT COUNT(*) FROM OPENJSON(@deleted))>1 ${deny}
 DECLARE @nd int=(SELECT COUNT(*) FROM OPENJSON(@deleted)),@id bigint=TRY_CONVERT(bigint,${I('id')}),@currency nvarchar(3)=${I('currency_code')},@amount decimal(18,4)=TRY_CONVERT(decimal(18,4),${I('amount')});
 IF @op=N'fixture_prepare' BEGIN
 IF ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 OR @nd<>0 OR @@TRANCOUNT<>1 OR ISNULL(APPLOCK_MODE(N'public',N'CLEAN_STORE_DAY_20261022',N'Transaction'),N'NoLock')<>N'Exclusive' ${deny}
 IF @table_name=N'finance_accounts' BEGIN IF NOT(${cashAccounts.filter(a=>a.id!==2).map(a=>`(@id=${a.id} AND ${I('account_code')}=N'${a.code}' AND @currency=N'${a.currency}' AND ${N('opening_balance')}=${a.opening} AND ${N('current_balance')}=${a.opening})`).join(' OR ')}) OR ${I('account_type')}<>N'cash' OR ISNULL(${I('is_active')},N'')<>N'true' ${deny} RETURN;END;
 IF @table_name=N'cash_drawers' BEGIN IF @id<>1 OR ${I('drawer_code')}<>N'B4-CEKMECE' OR ${I('drawer_name')}<>N'Örnek günlük çekmece' OR ISNULL(${I('is_active')},N'')<>N'true' ${deny} RETURN;END;
 IF @table_name=N'cash_drawer_accounts' BEGIN IF ${N('drawer_id')}<>1 OR ${N('finance_account_id')}<>CASE @currency WHEN N'TRY' THEN 2 WHEN N'USD' THEN 3 WHEN N'EUR' THEN 4 ELSE -1 END ${deny} RETURN;END;
 IF @table_name=N'expense_categories' BEGIN IF @id<>1 OR ${I('category_code')}<>N'B4-ORNEK' OR ${I('category_name')}<>N'Örnek günlük gider' OR ISNULL(${I('is_active')},N'')<>N'true' ${deny} RETURN;END;
 ${deny} END;
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' OR @actor NOT IN(20,10018) OR @op NOT IN(N'cash_open',N'cash_close',N'cash_transfer',N'cash_expense') ${deny}
 IF @table_name=N'finance_accounts' BEGIN
 IF @nd<>1 OR @id NOT BETWEEN 2 AND 7 OR ${N('current_balance')}<0 OR NOT EXISTS(SELECT 1 FROM dbo.finance_accounts a WHERE a.id=@id AND ${N('current_balance')}=a.opening_balance+COALESCE((SELECT SUM(CASE WHEN direction=N'in' THEN amount ELSE -amount END) FROM dbo.finance_account_movements WHERE account_id=a.id AND currency_code=a.currency_code),0)) ${deny}
 ${unchanged(['current_balance','updated_at'])} RETURN;END;
 IF @table_name=N'cash_sessions' BEGIN
 IF @op=N'cash_open' BEGIN IF @nd<>0 OR @id<=TRY_CONVERT(bigint,JSON_VALUE(@before,'$.session_max')) OR ${N('drawer_id')}<>1 OR TRY_CONVERT(date,${I('business_date')})<>CONVERT(date,'20261022',112) OR ${I('session_status')}<>N'open' OR ${N('opened_by')}<>@actor OR ISNULL(${I('opening_note')},N'')<>ISNULL(JSON_VALUE(@payload,'$.openingNote'),N'') OR ${I('closed_at')} IS NOT NULL OR ${I('closed_by')} IS NOT NULL ${deny} RETURN;END;
 IF @op<>N'cash_close' OR @nd<>1 OR @id<>@sid OR JSON_VALUE(@deleted,'$[0].session_status')<>N'open' OR ${I('session_status')}<>N'closed' OR ${N('closed_by')}<>@actor OR ISNULL(${I('closing_note')},N'')<>ISNULL(JSON_VALUE(@payload,'$.closingNote'),N'') OR TRY_CONVERT(datetime2,${I('closed_at')}) IS NULL ${deny}
 ${unchanged(['session_status','closing_note','closed_by','closed_at'])} RETURN;END;
 IF @table_name=N'cash_session_counts' BEGIN
 IF ${N('session_id')}<>@sid OR @currency IS NULL OR @currency NOT IN(N'TRY',N'USD',N'EUR') ${deny}
 DECLARE @physical decimal(18,4)=TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+@currency+CASE WHEN @op=N'cash_open' THEN N'.physicalOpening' ELSE N'.physicalClosing' END)),@second decimal(18,4)=TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+@currency+CASE WHEN @op=N'cash_open' THEN N'.openingTransfer' ELSE N'.carryForward' END)),@ledger decimal(18,4)=(SELECT current_balance FROM OPENJSON(@balances) WITH(id bigint,current_balance decimal(18,4)) WHERE id=CASE @currency WHEN N'TRY' THEN 2 WHEN N'USD' THEN 3 ELSE 4 END);
 IF @physical IS NULL OR @second IS NULL OR @ledger IS NULL ${deny}
 IF @op=N'cash_open' BEGIN IF @nd<>0 OR ${N('physical_opening_amount')}<>@physical OR ${N('opening_transfer_amount')}<>@second OR ${I('physical_closing_amount')} IS NOT NULL OR ${I('expected_closing_amount')} IS NOT NULL OR ${I('difference_amount')} IS NOT NULL OR ${I('carry_forward_amount')} IS NOT NULL OR ${I('transferred_to_main_amount')} IS NOT NULL ${deny} RETURN;END;
 IF @op<>N'cash_close' OR @nd<>1 OR ${N('expected_closing_amount')}<>@ledger OR ${N('physical_closing_amount')}<>@physical OR ${N('difference_amount')}<>@physical-@ledger OR ${N('carry_forward_amount')}<>@second OR ${N('transferred_to_main_amount')}<>@physical-@second ${deny}
 ${unchanged(['expected_closing_amount','physical_closing_amount','difference_amount','carry_forward_amount','transferred_to_main_amount'])} RETURN;END;
 IF @table_name IN(N'cash_transfers',N'cash_adjustments',N'cash_expenses') BEGIN
 IF @nd<>0 OR ${N('session_id')}<>@sid OR @currency IS NULL OR @currency NOT IN(N'TRY',N'USD',N'EUR') OR @amount IS NULL OR @amount<=0 OR @amount>10000 OR ${N('created_by')}<>@actor ${deny}
 IF @table_name=N'cash_transfers' BEGIN
 DECLARE @transferAmount decimal(18,4)=CASE @op WHEN N'cash_open' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+@currency+N'.openingTransfer')) WHEN N'cash_close' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+@currency+N'.physicalClosing'))-TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+@currency+N'.carryForward')) WHEN N'cash_transfer' THEN TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amount')) END;
 IF @id<=TRY_CONVERT(bigint,JSON_VALUE(@before,'$.transfer_max')) OR @transferAmount IS NULL OR @amount<>@transferAmount OR ${I('transfer_direction')}<>CASE @op WHEN N'cash_open' THEN N'main_to_drawer' WHEN N'cash_close' THEN N'drawer_to_main' ELSE JSON_VALUE(@payload,'$.direction') END OR(@op=N'cash_transfer' AND(@currency<>JSON_VALUE(@payload,'$.currency') OR ISNULL(${I('description')},N'')<>JSON_VALUE(@payload,'$.description'))) ${deny} RETURN;END;
 IF @table_name=N'cash_expenses' BEGIN IF @op<>N'cash_expense' OR @id<=TRY_CONVERT(bigint,JSON_VALUE(@before,'$.expense_max')) OR ${N('expense_category_id')}<>1 OR @currency<>JSON_VALUE(@payload,'$.currency') OR @amount<>TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amount')) OR ${I('description')}<>JSON_VALUE(@payload,'$.description') OR ISNULL(${I('document_no')},N'')<>ISNULL(JSON_VALUE(@payload,'$.documentNo'),N'') ${deny} RETURN;END;
 DECLARE @adjustLedger decimal(18,4)=(SELECT current_balance FROM OPENJSON(@balances) WITH(id bigint,current_balance decimal(18,4)) WHERE id=CASE @currency WHEN N'TRY' THEN 2 WHEN N'USD' THEN 3 ELSE 4 END),@adjustPhysical decimal(18,4)=TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,N'$.counts.'+@currency+CASE WHEN @op=N'cash_open' THEN N'.physicalOpening' ELSE N'.physicalClosing' END));
 IF @op NOT IN(N'cash_open',N'cash_close') OR @id<=TRY_CONVERT(bigint,JSON_VALUE(@before,'$.adjustment_max')) OR @adjustLedger IS NULL OR @adjustPhysical IS NULL OR @amount<>ABS(@adjustPhysical-@adjustLedger) OR ${I('adjustment_kind')}<>CASE WHEN @op=N'cash_open' THEN N'opening' ELSE N'closing' END OR ${I('direction')}<>CASE WHEN @adjustPhysical>@adjustLedger THEN N'in' ELSE N'out' END OR ISNULL(${I('reason')},N'')<>ISNULL(JSON_VALUE(@payload,CASE WHEN @op=N'cash_open' THEN '$.openingNote' ELSE '$.closingNote' END),N'') OR LEN(LTRIM(RTRIM(${I('reason')})))<5 ${deny} RETURN;END;
 IF @table_name=N'finance_account_movements' BEGIN
 IF @nd<>0 OR @id<=TRY_CONVERT(bigint,JSON_VALUE(@before,'$.finance_max')) OR ${N('account_id')} NOT BETWEEN 2 AND 7 OR @amount IS NULL OR @amount<=0 OR @amount>10000 OR ${I('payment_method')}<>N'cash' OR @currency NOT IN(N'TRY',N'USD',N'EUR') OR @currency IS NULL OR ${N('created_by')}<>@actor OR TRY_CONVERT(date,${I('document_date')})<>CONVERT(date,'20261022',112) ${deny}
 DECLARE @drawer bigint=CASE @currency WHEN N'TRY' THEN 2 WHEN N'USD' THEN 3 ELSE 4 END,@main bigint=CASE @currency WHEN N'TRY' THEN 5 WHEN N'USD' THEN 6 ELSE 7 END;
 IF ${I('source_type')}=N'cash_transfer' BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.cash_transfers t WHERE t.id=${N('party_movement_id')} AND t.id>TRY_CONVERT(bigint,JSON_VALUE(@before,'$.transfer_max')) AND t.session_id=@sid AND t.currency_code=@currency AND t.amount=@amount AND t.created_by=@actor AND((${I('party_type')}=N'main_cash' AND ${N('account_id')}=@main AND ${I('direction')}=CASE t.transfer_direction WHEN N'main_to_drawer' THEN N'out' ELSE N'in' END)OR(${I('party_type')}=N'cash_drawer' AND ${N('account_id')}=@drawer AND ${I('direction')}=CASE t.transfer_direction WHEN N'main_to_drawer' THEN N'in' ELSE N'out' END))) ${deny} RETURN;END;
 IF ${I('party_type')}<>N'cash_drawer' OR ${N('account_id')}<>@drawer ${deny}
 IF ${I('source_type')}=N'cash_adjustment' BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.cash_adjustments a WHERE a.id=${N('party_movement_id')} AND a.id>TRY_CONVERT(bigint,JSON_VALUE(@before,'$.adjustment_max')) AND a.session_id=@sid AND a.currency_code=@currency AND a.amount=@amount AND a.direction=${I('direction')} AND a.created_by=@actor) ${deny} RETURN;END;
 IF ${I('source_type')}=N'expense' BEGIN IF @op<>N'cash_expense' OR ${I('direction')}<>N'out' OR NOT EXISTS(SELECT 1 FROM dbo.cash_expenses e WHERE e.id=${N('party_movement_id')} AND e.id>TRY_CONVERT(bigint,JSON_VALUE(@before,'$.expense_max')) AND e.session_id=@sid AND e.currency_code=@currency AND e.amount=@amount AND e.created_by=@actor) ${deny} RETURN;END;
 ${deny} END;
 IF @table_name=N'work_trade_requests' BEGIN IF @nd<>0 OR ${N('actor_id')}<>@actor OR ${I('operation')}<>@op OR UPPER(${I('payload_hash')})<>@payloadHash OR ${I('payload_json')} COLLATE Latin1_General_100_BIN2<>@payload COLLATE Latin1_General_100_BIN2 OR LOWER(${I('request_id')})<>LOWER(CONVERT(nvarchar(36),@request)) ${deny} RETURN;END;
 IF @table_name=N'audit_logs' BEGIN
 IF @nd<>0 OR ${N('actor_user_id')}<>@actor OR ${I('action')}<>CASE @op WHEN N'cash_open' THEN N'cash_session_opened' WHEN N'cash_close' THEN N'cash_session_closed' WHEN N'cash_transfer' THEN N'cash_transfer_created' ELSE N'cash_expense_created' END OR ${I('entity_type')}<>CASE @op WHEN N'cash_transfer' THEN N'cash_transfer' WHEN N'cash_expense' THEN N'cash_expense' ELSE N'cash_session' END ${deny}
 IF @op IN(N'cash_open',N'cash_close') AND ${N('entity_id')}<>@sid ${deny}
 IF @op=N'cash_transfer' AND NOT EXISTS(SELECT 1 FROM dbo.cash_transfers WHERE id=${N('entity_id')} AND id>TRY_CONVERT(bigint,JSON_VALUE(@before,'$.transfer_max')) AND session_id=@sid AND created_by=@actor) ${deny}
 IF @op=N'cash_expense' AND NOT EXISTS(SELECT 1 FROM dbo.cash_expenses WHERE id=${N('entity_id')} AND id>TRY_CONVERT(bigint,JSON_VALUE(@before,'$.expense_max')) AND session_id=@sid AND created_by=@actor) ${deny} RETURN;END;
 ${deny} END;`;}
import {CLEAN_TARGET_SQL} from './clean-synthetic-sql.mjs';
import {CLEAN_LOGIN} from '../../apps/api/src/services/cleanSyntheticContext.mjs';
import {buildCleanOrderSaleProcedures} from './clean-order-sale-sql.mjs';
import {buildCleanStoreDayDefinitions,buildCleanStoreDayFinanceDefinitions,buildCleanStoreDayInventoryDefinitions,buildCleanInventoryCostFixtureDefinitions,buildCleanStoreAdministratorDefinitions} from './clean-store-day-cohort-sql.mjs';
const quote=s=>"N'"+s.replaceAll("'","''")+"'";
const deny="THROW 51965,'CLEAN_FINANCE_REHEARSAL_DENIED',1;";
const manifest='clean_finance_b4_manifest',intent='clean_finance_b4_intents',fixture='clean_finance_b4_fixture';
const I=k=>`JSON_VALUE(@inserted,N'$[0].${k}')`;
const N=k=>`ISNULL(TRY_CONVERT(decimal(28,8),${I(k)}),-999999)`;
const unchanged=allowed=>`IF EXISTS(SELECT 1 FROM OPENJSON(JSON_QUERY(@inserted,'$[0]')) i FULL JOIN OPENJSON(JSON_QUERY(@deleted,'$[0]')) d ON i.[key]=d.[key] WHERE COALESCE(i.[key],d.[key]) NOT IN(${allowed.map(quote).join(',')}) AND(i.[key] IS NULL OR d.[key] IS NULL OR i.[type]<>d.[type] OR ISNULL(i.value,N'') COLLATE Latin1_General_100_BIN2<>ISNULL(d.value,N'') COLLATE Latin1_General_100_BIN2)) ${deny}`;
const checks=`(SELECT OBJECT_NAME(parent_object_id) table_name,name,definition,is_disabled,is_not_trusted FROM sys.check_constraints WHERE parent_object_id IN(OBJECT_ID(N'dbo.work_trade_requests'),OBJECT_ID(N'dbo.stock_movements'),OBJECT_ID(N'dbo.supplier_movements')) ORDER BY parent_object_id,name FOR JSON PATH,INCLUDE_NULL_VALUES)`;
const getIntent=`DECLARE @actor bigint,@op nvarchar(40),@hash char(64),@payload nvarchar(max),@amount decimal(18,4),@original bigint,@accountBefore decimal(18,4),@customerBefore decimal(18,4),@supplierBefore decimal(18,4);SELECT @actor=actor_id,@op=operation,@hash=payload_hash,@payload=payload_json,@amount=amount,@original=original_id,@accountBefore=account_before,@customerBefore=customer_before,@supplierBefore=supplier_before FROM dbo.${intent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();IF @op IS NULL ${deny}`;
const witness=field=>`SELECT CONVERT(bit,1) ${field},CONVERT(varchar(36),environment_id) environmentId,LOWER(CONVERT(varchar(36),@request_id)) requestId,@actor actorId,@op operation,LOWER(@hash) payloadHash FROM dbo.clean_test_environment WHERE id=1;`;
const actorProof=`EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id JOIN dbo.permissions p ON p.role_id=r.id WHERE u.id=@actor_id AND u.is_active=1 AND r.is_active=1 AND((@operation IN(N'collection_create',N'payment') AND((u.id=20 AND u.username=N'ornek-finans' AND r.id=25 AND r.code=N'clean_test_finance')OR(u.id=10018 AND u.username=N'semih' AND r.id=28 AND r.code=N'clean_test_administrator')))OR(@operation IN(N'collection_cancel',N'payment_cancel') AND u.id=23 AND u.username=N'ornek-finans-kontrol' AND r.id=29 AND r.code=N'clean_test_finance_checker')) AND p.permission_key=@permission AND p.can_create=1)`;
export function buildCleanFinanceRehearsalPredecessors(){
 const day=buildCleanStoreDayDefinitions();
 // The cohort installs these upgraded guards separately from its procedures.
 // SQL stores the original CREATE spelling after ALTER; retain its exact body.
 const guards=Object.fromEntries(day.guards.map(g=>{
  const body=g.definition.replace(/^ALTER TRIGGER/,'CREATE TRIGGER');
  if(moduleHash(body)!==g.afterHash)throw Error('B4 inbound guard predecessor changed: '+g.name);
  return [g.name,body];
 }));
 return {...buildCleanOrderSaleProcedures(),...day.definitions,...guards,...buildCleanStoreDayFinanceDefinitions().definitions,...buildCleanStoreDayInventoryDefinitions().definitions,...buildCleanInventoryCostFixtureDefinitions().definitions,...buildCleanStoreAdministratorDefinitions().definitions};
}
function prefix(body,table){const at=body.indexOf('AS BEGIN')+8;if(at<8)throw Error('B4 predecessor body missing');return body.slice(0,at)+`\n IF EXISTS(SELECT 1 FROM dbo.${intent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) BEGIN DECLARE @b4i nvarchar(max)=(SELECT * FROM inserted FOR JSON PATH,INCLUDE_NULL_VALUES),@b4d nvarchar(max)=(SELECT * FROM deleted FOR JSON PATH,INCLUDE_NULL_VALUES);EXEC dbo.usp_clean_finance_b4_guard N'${table}',@b4i,@b4d;RETURN;END;\n`+body.slice(at);}
export function buildCleanFinanceRehearsalDefinitions(){
 const prior=buildCleanFinanceRehearsalPredecessors(),defs={};
 defs.usp_clean_finance_b4_ready=`CREATE PROCEDURE dbo.usp_clean_finance_b4_ready @verify_balances bit=0 WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' AND ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 ${deny}
 IF(SELECT COUNT(*) FROM dbo.${manifest})<>/*B4_COUNT*/ OR EXISTS(SELECT 1 FROM dbo.${manifest} m WHERE m.after_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name)) IS NULL OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'ExecIsTriggerDisabled')<>0)) ${deny}
 IF(SELECT COUNT(*) FROM dbo.${fixture})<>1 OR NOT EXISTS(SELECT 1 FROM dbo.${fixture} f JOIN dbo.customers c ON c.id=f.customer_id JOIN dbo.suppliers s ON s.id=f.supplier_id JOIN dbo.finance_accounts a ON a.id=f.account_id JOIN dbo.sales_invoices i ON i.id=f.sales_invoice_id JOIN dbo.purchase_invoices p ON p.id=f.purchase_invoice_id WHERE f.id=1 AND f.case_id=N'B4-TRY-20261023' AND f.customer_id=2 AND f.supplier_id=2 AND f.account_id=2 AND f.sales_invoice_id=2 AND f.purchase_invoice_id=5 AND f.currency=N'TRY' AND f.operation_date=CONVERT(date,'20261022',112) AND c.customer_code=N'B4-ORNEK-M' AND c.name=N'B4 Örnek Müşteri' AND c.currency_code=N'TRY' AND c.is_active=1 AND c.is_deleted=0 AND s.supplier_code=N'B4-ORNEK-T' AND s.name=N'B4 Örnek Tedarikçi' AND s.currency_code=N'TRY' AND s.is_active=1 AND s.is_deleted=0 AND a.account_code=N'B4-ORNEK-TRY' AND a.currency_code=N'TRY' AND a.account_type=N'cash' AND a.opening_balance=0 AND a.is_active=1 AND i.document_no=N'B4-ORNEK-TAHSILAT' AND i.customer_id=2 AND i.status=N'finalized' AND i.document_currency=N'TRY' AND i.grand_total=251 AND i.account_amount=251 AND i.account_currency=N'TRY' AND i.exchange_rate_snapshot=1 AND i.account_exchange_rate_snapshot=1 AND p.document_no=N'B4-ORNEK-ODEME' AND p.supplier_id=2 AND p.status=N'finalized' AND p.document_currency=N'TRY' AND p.grand_total=200 AND p.account_amount=200 AND p.account_currency=N'TRY' AND p.exchange_rate_snapshot=1 AND p.account_exchange_rate_snapshot=1) ${deny}
 IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds WHERE(entity=N'customer' AND native_id=2)OR(entity=N'supplier' AND native_id=2)OR(entity=N'product' AND native_id=1)) ${deny}
 IF @verify_balances=1 AND(NOT EXISTS(SELECT 1 FROM dbo.customers c WHERE c.id=2 AND c.balance=(SELECT COALESCE(SUM(balance_effect),0) FROM dbo.customer_movements WHERE customer_id=2 AND currency_code=N'TRY')) OR NOT EXISTS(SELECT 1 FROM dbo.suppliers s WHERE s.id=2 AND s.balance=(SELECT COALESCE(SUM(balance_effect),0) FROM dbo.supplier_movements WHERE supplier_id=2 AND currency_code=N'TRY')) OR NOT EXISTS(SELECT 1 FROM dbo.finance_accounts a WHERE a.id=2 AND a.current_balance=(SELECT COALESCE(SUM(CASE WHEN direction=N'in' THEN amount ELSE -amount END),0) FROM dbo.finance_account_movements WHERE account_id=2 AND currency_code=N'TRY'))) ${deny}
 END;`;
 defs.usp_clean_finance_b4_bind=`CREATE PROCEDURE dbo.usp_clean_finance_b4_bind @actor_id bigint,@operation nvarchar(40),@request_id uniqueidentifier,@payload_hash char(64),@payload_json nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;${CLEAN_TARGET_SQL}
 EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_ready @verify_balances=1;
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' OR @@TRANCOUNT<>1 OR ISNULL(APPLOCK_MODE(N'public',N'CLEAN_STORE_DAY_20261022',N'Transaction'),N'NoLock')<>N'Exclusive' OR EXISTS(SELECT 1 FROM dbo.${intent} WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_store_day_intents WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_store_inventory_intents WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_intents WHERE session_id=@@SPID) ${deny}
 DECLARE @permission nvarchar(80)=CASE @operation WHEN N'collection_create' THEN N'finance.collection' WHEN N'collection_cancel' THEN N'finance.collection.cancel' WHEN N'payment' THEN N'finance.payment' WHEN N'payment_cancel' THEN N'finance.payment.cancel' END;
 IF @request_id IS NULL OR @payload_json IS NULL OR @payload_hash IS NULL OR @permission IS NULL OR NOT ${actorProof} OR ISJSON(@payload_json)<>1 OR LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',@payload_json),2))<>LOWER(@payload_hash) OR ISNULL(JSON_VALUE(@payload_json,'$.actorId'),N'')<>CONVERT(nvarchar(20),@actor_id) OR ISNULL(JSON_VALUE(@payload_json,'$.operation'),N'')<>@operation OR LOWER(JSON_VALUE(@payload_json,'$.requestId'))<>LOWER(CONVERT(nvarchar(36),@request_id)) OR ISNULL(TRY_CONVERT(date,JSON_VALUE(@payload_json,'$.documentDate')),CONVERT(date,'19000101',112))<>CONVERT(date,'20261022',112) OR EXISTS(SELECT 1 FROM OPENJSON(@payload_json) WHERE [key] NOT IN(N'actorId',N'operation',N'requestId',N'previewHash',N'expectedRevision',N'invoiceId',N'accountId',N'amountExact4',N'documentDate',N'supplierId',N'currency',N'description',N'id',N'reason')) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.work_trade_requests WHERE request_id=@request_id) ${deny}
 DECLARE @amount decimal(18,4),@original bigint=NULL,@account decimal(18,4),@customer decimal(18,4),@supplier decimal(18,4);
 SELECT @account=current_balance FROM dbo.finance_accounts WITH(UPDLOCK,HOLDLOCK) WHERE id=2;SELECT @customer=balance FROM dbo.customers WITH(UPDLOCK,HOLDLOCK) WHERE id=2;SELECT @supplier=balance FROM dbo.suppliers WITH(UPDLOCK,HOLDLOCK) WHERE id=2;
 IF @operation IN(N'collection_create',N'payment') BEGIN
 SET @amount=TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,'$.amountExact4'));IF @amount IS NULL OR @amount<=0 OR @amount>500 OR TRY_CONVERT(decimal(28,8),JSON_VALUE(@payload_json,'$.amountExact4'))<>@amount OR ISNULL(JSON_VALUE(@payload_json,'$.accountId'),N'')<>N'2' ${deny}
 IF @operation=N'collection_create' AND(ISNULL(JSON_VALUE(@payload_json,'$.invoiceId'),N'')<>N'2' OR @amount>@customer OR @amount>251-COALESCE((SELECT SUM(CASE WHEN m.movement_type=N'collection' THEN m.amount ELSE -m.amount END) FROM dbo.work_collection_links l JOIN dbo.customer_movements m ON m.id=l.movement_id WHERE l.invoice_id=2),0)) ${deny}
 IF @operation=N'payment' AND(ISNULL(JSON_VALUE(@payload_json,'$.supplierId'),N'')<>N'2' OR ISNULL(JSON_VALUE(@payload_json,'$.invoiceId'),N'')<>N'5' OR ISNULL(JSON_VALUE(@payload_json,'$.currency'),N'')<>N'TRY' OR @amount>@supplier OR @amount>@account) ${deny}
 END ELSE BEGIN
 SET @original=TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.id'));IF @original IS NULL OR LEN(LTRIM(RTRIM(ISNULL(JSON_VALUE(@payload_json,'$.reason'),N''))))<5 OR LEN(JSON_VALUE(@payload_json,'$.reason'))>300 ${deny}
 IF @operation=N'collection_cancel' BEGIN
 SELECT @amount=m.amount FROM dbo.customer_movements m JOIN dbo.work_collection_links l ON l.movement_id=m.id AND l.invoice_id=2 AND l.original_id IS NULL JOIN dbo.finance_account_movements f ON f.party_type=N'customer' AND f.party_movement_id=m.id AND f.source_type=N'collection' AND f.account_id=2 WHERE m.id=@original AND m.customer_id=2 AND m.sales_invoice_id=2 AND m.movement_type=N'collection' AND m.currency_code=N'TRY' AND m.account_currency=N'TRY' AND m.amount=m.account_amount AND m.amount=m.amount_try AND m.document_exchange_rate_snapshot=1 AND m.account_exchange_rate_snapshot=1 AND m.created_by=@actor_id AND EXISTS(SELECT 1 FROM dbo.work_trade_requests j WHERE j.actor_id=@actor_id AND j.operation=N'collection_create' AND TRY_CONVERT(bigint,JSON_VALUE(j.response_json,'$.collection.id'))=m.id) AND NOT EXISTS(SELECT 1 FROM dbo.work_collection_links x WHERE x.original_id=m.id);
 IF @amount>@account ${deny}
 END ELSE BEGIN
 SELECT @amount=m.amount FROM dbo.supplier_movements m JOIN dbo.finance_account_movements f ON f.party_type=N'supplier' AND f.party_movement_id=m.id AND f.source_type=N'payment' AND f.account_id=2 WHERE m.id=@original AND m.supplier_id=2 AND m.purchase_invoice_id=5 AND m.movement_type=N'payment' AND m.currency_code=N'TRY' AND m.account_currency=N'TRY' AND m.amount=m.account_amount AND m.amount=m.amount_try AND m.document_exchange_rate_snapshot=1 AND m.account_exchange_rate_snapshot=1 AND m.created_by=@actor_id AND EXISTS(SELECT 1 FROM dbo.work_trade_requests j WHERE j.actor_id=@actor_id AND j.operation=N'payment' AND TRY_CONVERT(bigint,JSON_VALUE(j.response_json,'$.payment.id'))=m.id) AND NOT EXISTS(SELECT 1 FROM dbo.work_trade_requests j WHERE j.operation=N'payment_cancel' AND TRY_CONVERT(bigint,JSON_VALUE(j.response_json,'$.payment.originalId'))=m.id);
 END;
 IF @amount IS NULL OR @amount<=0 OR @amount>500 ${deny}
 END;
 INSERT dbo.${intent}(session_id,transaction_id,request_id,actor_id,operation,payload_hash,payload_json,amount,original_id,account_before,customer_before,supplier_before,customer_count_before,supplier_count_before,finance_count_before,customer_max_before,supplier_max_before,stock_count_before,stock_hash_before)
 SELECT @@SPID,CURRENT_TRANSACTION_ID(),@request_id,@actor_id,@operation,UPPER(@payload_hash),@payload_json,@amount,@original,@account,@customer,@supplier,(SELECT COUNT(*) FROM dbo.customer_movements),(SELECT COUNT(*) FROM dbo.supplier_movements),(SELECT COUNT(*) FROM dbo.finance_account_movements),(SELECT COALESCE(MAX(id),0) FROM dbo.customer_movements),(SELECT COALESCE(MAX(id),0) FROM dbo.supplier_movements),(SELECT COUNT(*) FROM dbo.stock_movements),HASHBYTES('SHA2_256',(SELECT id,current_stock_qty,average_cost_try FROM dbo.products ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES));
 DECLARE @actor bigint=@actor_id,@op nvarchar(40)=@operation,@hash char(64)=@payload_hash;${witness('accepted')} END;`;
 defs.usp_clean_finance_b4_guard=guardDefinition();
 defs.usp_clean_finance_b4_finish=finishDefinition();
 for(const [name,table] of [['clean_sale_customers_guard','customers'],['clean_sale_customer_movements_guard','customer_movements'],['clean_sale_sales_invoices_guard','sales_invoices'],['clean_sale_sales_invoice_items_guard','sales_invoice_items'],['clean_sale_audit_logs_guard','audit_logs']])defs[name]=prefix(prior[name],table);
 for(const name of ['usp_clean_store_day_guard','usp_clean_store_finance_guard']){const body=prior[name],at=body.indexOf('AS BEGIN')+8;defs[name]=body.slice(0,at)+`\n IF EXISTS(SELECT 1 FROM dbo.${intent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) BEGIN EXEC dbo.usp_clean_finance_b4_guard @table_name,@inserted,@deleted;RETURN;END;\n`+body.slice(at);}
 let ready=prior.usp_clean_store_day_ready;
 for(const alias of ['cf','d','e','f','v','a']){const hash=`CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+${alias}.name))),2)`;ready=ready.replaceAll(hash,`COALESCE((SELECT b4.before_hash FROM dbo.${manifest} b4 WHERE b4.name=${alias}.name AND b4.after_hash=${hash}),${hash})`);}
 ready=ready.replace('(SELECT after_constraints_hash FROM dbo.clean_store_administrator_manifest',`(SELECT after_constraints_hash FROM dbo.${manifest}`);
 const oldAccount="OR EXISTS(SELECT 1 FROM dbo.finance_accounts WHERE id<>1)";
 if(!ready.includes(oldAccount))throw Error('B4 finance account predecessor changed');
 ready=ready.replace(oldAccount,`OR EXISTS(SELECT 1 FROM dbo.finance_accounts a WHERE a.id<>1 AND NOT EXISTS(SELECT 1 FROM dbo.${fixture} f WHERE f.account_id=a.id AND f.id=1 AND a.id=2 AND a.account_code=N'B4-ORNEK-TRY' AND a.currency_code=N'TRY' AND a.account_type=N'cash' AND a.opening_balance=0 AND a.is_active=1))`);
 defs.usp_clean_store_day_ready=ready.replace('\n END;',`\n EXEC dbo.usp_clean_finance_b4_ready;\n END;`);
 defs.clean_finance_b4_manifest_immutable=`CREATE TRIGGER dbo.clean_finance_b4_manifest_immutable ON dbo.${manifest} AFTER INSERT,UPDATE,DELETE AS BEGIN ${deny} END;`;
 defs.clean_finance_b4_fixture_immutable=`CREATE TRIGGER dbo.clean_finance_b4_fixture_immutable ON dbo.${fixture} AFTER INSERT,UPDATE,DELETE AS BEGIN IF EXISTS(SELECT 1 FROM deleted) OR ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.${intent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID() AND operation=N'fixture_prepare') OR(SELECT COUNT(*) FROM inserted)<>1 OR NOT EXISTS(SELECT 1 FROM inserted WHERE id=1 AND case_id=N'B4-TRY-20261023' AND customer_id=2 AND supplier_id=2 AND account_id=2 AND sales_invoice_id=2 AND purchase_invoice_id=5 AND currency=N'TRY' AND operation_date=CONVERT(date,'20261022',112)) ${deny} END;`;
 const total=Object.keys(defs).length;for(const n of Object.keys(defs))defs[n]=defs[n].replaceAll('/*B4_COUNT*/',String(total));
 // A separate, normally authenticated TEST checker reverses only this finite
 // case's journalled payments. Existing creators and their roles are unchanged.
 defs.usp_clean_finance_b4_guard=defs.usp_clean_finance_b4_guard.replace('@actor NOT IN(20,10018)','@actor NOT IN(20,23,10018)');
 for(const part of ["m.created_by=@actor_id AND EXISTS(SELECT 1 FROM dbo.work_trade_requests j WHERE j.actor_id=@actor_id AND j.operation=N'collection_create'","m.created_by=@actor_id AND EXISTS(SELECT 1 FROM dbo.work_trade_requests j WHERE j.actor_id=@actor_id AND j.operation=N'payment'"]){
  if(!defs.usp_clean_finance_b4_bind.includes(part))throw Error('B4 cancellation predecessor changed');
  defs.usp_clean_finance_b4_bind=defs.usp_clean_finance_b4_bind.replace(part,part.replace('m.created_by=@actor_id','m.created_by IN(20,10018)').replace('j.actor_id=@actor_id','j.actor_id=m.created_by'));
 }
 return {definitions:defs,before:Object.fromEntries(Object.keys(defs).filter(n=>prior[n]).map(n=>[n,prior[n]])),total};
}

function guardDefinition(){return `CREATE PROCEDURE dbo.usp_clean_finance_b4_guard @table_name sysname,@inserted nvarchar(max),@deleted nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}${getIntent}
 IF ISJSON(@inserted)<>1 OR ISJSON(@deleted)<>1 OR(SELECT COUNT(*) FROM OPENJSON(@inserted))<>1 OR(SELECT COUNT(*) FROM OPENJSON(@deleted))>1 ${deny}
 DECLARE @nd int=(SELECT COUNT(*) FROM OPENJSON(@deleted));
 IF @op=N'fixture_prepare' BEGIN
 IF ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 OR @nd<>0 OR @@TRANCOUNT<>1 OR ISNULL(APPLOCK_MODE(N'public',N'CLEAN_STORE_DAY_20261022',N'Transaction'),N'NoLock')<>N'Exclusive' ${deny}
 ${fixtureGuardBranches()}
 ${deny} END;
 EXEC dbo.usp_clean_finance_b4_ready;
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' OR @actor NOT IN(20,10018) OR @op NOT IN(N'collection_create',N'collection_cancel',N'payment',N'payment_cancel') ${deny}
 DECLARE @role nvarchar(20)=CASE WHEN @op LIKE N'collection%' THEN N'customer' ELSE N'supplier' END,@kind nvarchar(30)=CASE @op WHEN N'collection_create' THEN N'collection' ELSE @op END,@cancel bit=CASE WHEN @op LIKE N'%[_]cancel' THEN 1 ELSE 0 END,@partySign int=CASE WHEN @op LIKE N'%[_]cancel' THEN 1 ELSE -1 END,@cashSign int=CASE WHEN @op IN(N'collection_create',N'payment_cancel') THEN 1 ELSE -1 END;
 IF @table_name IN(N'customers',N'suppliers') BEGIN
 IF @table_name<>@role+N's' OR @nd<>1 OR ${N('id')}<>2 OR ${N('balance')}<>CASE WHEN @role=N'customer' THEN @customerBefore ELSE @supplierBefore END+@partySign*@amount ${deny}
 ${unchanged(['balance','updated_at','row_version'])} RETURN;END;
 IF @table_name IN(N'customer_movements',N'supplier_movements') BEGIN
 IF @table_name<>@role+N'_movements' OR ${N('amount')}<>@amount OR ${N('balance_effect')}<>@partySign*@amount OR ${I('movement_type')}<>@kind OR ${I('currency_code')}<>N'TRY' OR ${N('created_by')}<>@actor OR TRY_CONVERT(date,${I('document_date')})<>CONVERT(date,'20261022',112) OR ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@inserted,N'$[0].'+@role+N'_id')),-1)<>2 OR ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@inserted,CASE WHEN @role=N'customer' THEN N'$[0].sales_invoice_id' ELSE N'$[0].purchase_invoice_id' END)),-1)<>CASE WHEN @role=N'customer' THEN 2 ELSE 5 END OR ${N('id')}<=CASE WHEN @role=N'customer' THEN(SELECT customer_max_before FROM dbo.${intent} WHERE session_id=@@SPID)ELSE(SELECT supplier_max_before FROM dbo.${intent} WHERE session_id=@@SPID)END ${deny}
 IF ${I('account_currency')} IS NOT NULL AND(${I('account_currency')}<>N'TRY' OR ${N('account_amount')}<>@amount OR ${N('amount_try')}<>@amount OR ${N('account_exchange_rate_snapshot')}<>1 OR ${N('document_exchange_rate_snapshot')}<>1) ${deny}
 IF @nd=1 BEGIN ${unchanged(['account_currency','account_amount','account_exchange_rate_snapshot','document_exchange_rate_snapshot','amount_try','balance_effect'])} END;RETURN;END;
 IF @table_name=N'finance_accounts' BEGIN IF @nd<>1 OR ${N('id')}<>2 OR ${N('current_balance')}<>@accountBefore+@cashSign*@amount OR TRY_CONVERT(decimal(18,4),JSON_VALUE(@deleted,'$[0].current_balance'))<>@accountBefore ${deny} ${unchanged(['current_balance','updated_at'])} RETURN;END;
 IF @table_name=N'finance_account_movements' BEGIN
 IF @nd<>0 OR ${N('account_id')}<>2 OR ${I('source_type')}<>@kind OR ${I('party_type')}<>@role OR ${I('direction')}<>CASE WHEN @cashSign=1 THEN N'in' ELSE N'out' END OR ${N('amount')}<>@amount OR ${I('currency_code')}<>N'TRY' OR ${I('payment_method')}<>N'cash' OR ${N('created_by')}<>@actor OR TRY_CONVERT(date,${I('document_date')})<>CONVERT(date,'20261022',112) ${deny}
 IF @role=N'customer' AND NOT EXISTS(SELECT 1 FROM dbo.customer_movements m JOIN dbo.${intent} t ON t.session_id=@@SPID WHERE m.id=${N('party_movement_id')} AND m.id>t.customer_max_before AND m.customer_id=2 AND m.sales_invoice_id=2 AND m.movement_type=@kind AND m.amount=@amount AND m.account_amount=@amount AND m.account_currency=N'TRY' AND m.amount_try=@amount) ${deny}
 IF @role=N'supplier' AND NOT EXISTS(SELECT 1 FROM dbo.supplier_movements m JOIN dbo.${intent} t ON t.session_id=@@SPID WHERE m.id=${N('party_movement_id')} AND m.id>t.supplier_max_before AND m.supplier_id=2 AND m.purchase_invoice_id=5 AND m.movement_type=@kind AND m.amount=@amount AND m.account_amount=@amount AND m.account_currency=N'TRY' AND m.amount_try=@amount) ${deny} RETURN;END;
 IF @table_name=N'work_collection_links' BEGIN IF @role<>N'customer' OR @nd<>0 OR ${N('invoice_id')}<>2 OR(@cancel=0 AND ${I('original_id')} IS NOT NULL)OR(@cancel=1 AND ${N('original_id')}<>@original) OR NOT EXISTS(SELECT 1 FROM dbo.customer_movements m JOIN dbo.finance_account_movements f ON f.party_movement_id=m.id AND f.party_type=N'customer' AND f.source_type=@kind JOIN dbo.${intent} t ON t.session_id=@@SPID WHERE m.id=${N('movement_id')} AND m.id>t.customer_max_before AND m.sales_invoice_id=2 AND m.amount=@amount AND f.account_id=2) ${deny} RETURN;END;
 IF @table_name=N'work_trade_requests' BEGIN IF @nd<>0 OR ${N('actor_id')}<>@actor OR ${I('operation')}<>@op OR UPPER(${I('payload_hash')})<>@hash OR ${I('payload_json')} COLLATE Latin1_General_100_BIN2<>@payload COLLATE Latin1_General_100_BIN2 OR LOWER(${I('request_id')})<>LOWER(CONVERT(nvarchar(36),(SELECT request_id FROM dbo.${intent} WHERE session_id=@@SPID))) ${deny} RETURN;END;
 IF @table_name=N'audit_logs' BEGIN IF @nd<>0 OR ${N('actor_user_id')}<>@actor OR ${I('action')}<>CASE @op WHEN N'collection_create' THEN N'customer_collection_created' WHEN N'payment' THEN N'supplier_payment_created' WHEN N'collection_cancel' THEN N'collection_cancel' ELSE N'supplier_payment_cancelled' END OR ${I('entity_type')}<>@role+N'_movement' ${deny}
 IF @role=N'customer' AND NOT EXISTS(SELECT 1 FROM dbo.customer_movements m JOIN dbo.${intent} t ON t.session_id=@@SPID WHERE m.id=${N('entity_id')} AND m.id>t.customer_max_before AND m.customer_id=2 AND m.sales_invoice_id=2 AND m.movement_type=@kind AND m.amount=@amount) ${deny}
 IF @role=N'supplier' AND NOT EXISTS(SELECT 1 FROM dbo.supplier_movements m JOIN dbo.${intent} t ON t.session_id=@@SPID WHERE m.id=${N('entity_id')} AND m.id>t.supplier_max_before AND m.supplier_id=2 AND m.purchase_invoice_id=5 AND m.movement_type=@kind AND m.amount=@amount) ${deny} RETURN;END;
 ${deny} END;`;}

function fixtureGuardBranches(){return `
 IF @table_name=N'customers' BEGIN IF ${N('id')}<>2 OR ${I('customer_code')}<>N'B4-ORNEK-M' OR ${I('name')}<>N'B4 Örnek Müşteri' OR ${I('currency_code')}<>N'TRY' OR ${N('balance')}<>251 OR ${N('created_by')}<>10018 OR ISNULL(${I('is_active')},N'')<>N'true' OR ISNULL(${I('is_deleted')},N'')<>N'false' ${deny} RETURN;END;
 IF @table_name=N'suppliers' BEGIN IF ${N('id')}<>2 OR ${I('supplier_code')}<>N'B4-ORNEK-T' OR ${I('name')}<>N'B4 Örnek Tedarikçi' OR ${I('currency_code')}<>N'TRY' OR ${N('balance')}<>200 OR ${N('created_by')}<>10018 OR ISNULL(${I('is_active')},N'')<>N'true' OR ISNULL(${I('is_deleted')},N'')<>N'false' ${deny} RETURN;END;
 IF @table_name=N'finance_accounts' BEGIN IF ${N('id')}<>2 OR ${I('account_code')}<>N'B4-ORNEK-TRY' OR ${I('account_name')}<>N'B4 Örnek TRY kasası' OR ${I('account_type')}<>N'cash' OR ${I('currency_code')}<>N'TRY' OR ${N('opening_balance')}<>0 OR ${N('current_balance')}<>0 OR ISNULL(${I('is_active')},N'')<>N'true' ${deny} RETURN;END;
 IF @table_name=N'sales_invoices' BEGIN IF ${N('id')}<>2 OR ${N('customer_id')}<>2 OR ${I('document_no')}<>N'B4-ORNEK-TAHSILAT' OR ${I('status')}<>N'finalized' OR ${I('document_currency')}<>N'TRY' OR ${I('customer_currency')}<>N'TRY' OR ${N('subtotal')}<>251 OR ${N('grand_total')}<>251 OR ${N('amount_try')}<>251 OR ${N('exchange_rate_snapshot')}<>1 OR ${N('account_amount')}<>251 OR ${I('account_currency')}<>N'TRY' OR ${N('account_exchange_rate_snapshot')}<>1 OR ${N('created_by')}<>10018 ${deny} RETURN;END;
 IF @table_name=N'purchase_invoices' BEGIN IF ${N('id')}<>5 OR ${N('supplier_id')}<>2 OR ${I('document_no')}<>N'B4-ORNEK-ODEME' OR ${I('status')}<>N'finalized' OR ${I('document_currency')}<>N'TRY' OR ${I('supplier_currency')}<>N'TRY' OR ${N('subtotal')}<>200 OR ${N('grand_total')}<>200 OR ${N('amount_try')}<>200 OR ${N('exchange_rate_snapshot')}<>1 OR ${N('account_amount')}<>200 OR ${I('account_currency')}<>N'TRY' OR ${N('account_exchange_rate_snapshot')}<>1 OR ${N('created_by')}<>10018 ${deny} RETURN;END;
 IF @table_name=N'sales_invoice_items' BEGIN IF ${N('sales_invoice_id')}<>2 OR ${N('product_id')}<>1 OR ${N('quantity')}<>2 OR ${N('unit_price')}<>125.5 OR ${N('line_total')}<>251 OR ${I('currency_code')}<>N'TRY' OR ${I('stock_code_snapshot')}<>N'0007 MELISA' ${deny} RETURN;END;
 IF @table_name=N'purchase_invoice_items' BEGIN IF ${N('purchase_invoice_id')}<>5 OR ${N('product_id')}<>1 OR ${N('quantity')}<>2 OR ${N('purchase_price')}<>100 OR ${N('line_total')}<>200 OR ${N('line_total_try')}<>200 OR ${I('currency_code')}<>N'TRY' OR ${I('stock_code_snapshot')}<>N'0007 MELISA' ${deny} RETURN;END;
 IF @table_name=N'customer_movements' BEGIN IF ${N('customer_id')}<>2 OR ${N('sales_invoice_id')}<>2 OR ${I('movement_type')}<>N'sales_invoice' OR ${N('amount')}<>251 OR ${N('balance_effect')}<>251 OR ${I('currency_code')}<>N'TRY' OR ${N('created_by')}<>10018 OR ${I('account_currency')}<>N'TRY' OR ${N('account_amount')}<>251 OR ${N('amount_try')}<>251 OR ${N('document_exchange_rate_snapshot')}<>1 OR ${N('account_exchange_rate_snapshot')}<>1 ${deny} RETURN;END;
 IF @table_name=N'supplier_movements' BEGIN IF ${N('supplier_id')}<>2 OR ${N('purchase_invoice_id')}<>5 OR ${I('movement_type')}<>N'purchase_invoice' OR ${N('amount')}<>200 OR ${N('balance_effect')}<>200 OR ${I('currency_code')}<>N'TRY' OR ${N('created_by')}<>10018 OR ${I('account_currency')}<>N'TRY' OR ${N('account_amount')}<>200 OR ${N('amount_try')}<>200 OR ${N('document_exchange_rate_snapshot')}<>1 OR ${N('account_exchange_rate_snapshot')}<>1 ${deny} RETURN;END;`;}

function finishDefinition(){return `CREATE PROCEDURE dbo.usp_clean_finance_b4_finish @request_id uniqueidentifier WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;${CLEAN_TARGET_SQL}${getIntent}
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' OR @op NOT IN(N'collection_create',N'collection_cancel',N'payment',N'payment_cancel') OR NOT EXISTS(SELECT 1 FROM dbo.${intent} WHERE session_id=@@SPID AND request_id=@request_id) ${deny}
 DECLARE @customer bit=CASE WHEN @op LIKE N'collection%' THEN 1 ELSE 0 END,@cancel bit=CASE WHEN @op LIKE N'%[_]cancel' THEN 1 ELSE 0 END,@response nvarchar(max),@movement bigint,@kind nvarchar(30)=CASE WHEN @op=N'collection_create' THEN N'collection' ELSE @op END;
 SELECT @response=response_json FROM dbo.work_trade_requests WHERE request_id=@request_id AND actor_id=@actor AND operation=@op AND payload_hash=@hash AND payload_json=@payload;IF @response IS NULL ${deny}
 IF @customer=1 AND @cancel=1 BEGIN SELECT @movement=movement_id FROM dbo.work_collection_links WHERE original_id=@original AND invoice_id=2;IF TRY_CONVERT(bigint,JSON_VALUE(@response,'$.collection.id'))<>@original OR JSON_VALUE(@response,'$.collection.status')<>N'cancelled' ${deny} END;
 ELSE SET @movement=TRY_CONVERT(bigint,JSON_VALUE(@response,CASE WHEN @customer=1 THEN '$.collection.id' ELSE '$.payment.id' END));
 IF @movement IS NULL OR HASHBYTES('SHA2_256',(SELECT id,current_stock_qty,average_cost_try FROM dbo.products ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES))<>(SELECT stock_hash_before FROM dbo.${intent} WHERE session_id=@@SPID) OR(SELECT COUNT(*) FROM dbo.stock_movements)<>(SELECT stock_count_before FROM dbo.${intent} WHERE session_id=@@SPID) ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.finance_accounts WHERE id=2 AND current_balance=@accountBefore+CASE WHEN @op IN(N'collection_create',N'payment_cancel') THEN @amount ELSE -@amount END) OR NOT EXISTS(SELECT 1 FROM dbo.customers WHERE id=2 AND balance=@customerBefore+CASE WHEN @customer=0 THEN 0 WHEN @cancel=1 THEN @amount ELSE -@amount END) OR NOT EXISTS(SELECT 1 FROM dbo.suppliers WHERE id=2 AND balance=@supplierBefore+CASE WHEN @customer=1 THEN 0 WHEN @cancel=1 THEN @amount ELSE -@amount END) ${deny}
 IF(SELECT COUNT(*) FROM dbo.customer_movements)<>(SELECT customer_count_before FROM dbo.${intent} WHERE session_id=@@SPID)+CASE WHEN @customer=1 THEN 1 ELSE 0 END OR(SELECT COUNT(*) FROM dbo.supplier_movements)<>(SELECT supplier_count_before FROM dbo.${intent} WHERE session_id=@@SPID)+CASE WHEN @customer=0 THEN 1 ELSE 0 END OR(SELECT COUNT(*) FROM dbo.finance_account_movements)<>(SELECT finance_count_before FROM dbo.${intent} WHERE session_id=@@SPID)+1 ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.finance_account_movements WHERE account_id=2 AND party_movement_id=@movement AND party_type=CASE WHEN @customer=1 THEN N'customer' ELSE N'supplier' END AND source_type=@kind AND amount=@amount AND currency_code=N'TRY' AND created_by=@actor) ${deny}
 IF @customer=1 AND NOT EXISTS(SELECT 1 FROM dbo.customer_movements m JOIN dbo.work_collection_links l ON l.movement_id=m.id AND l.invoice_id=2 WHERE m.id=@movement AND m.customer_id=2 AND m.sales_invoice_id=2 AND m.movement_type=@kind AND m.amount=@amount AND m.balance_effect=CASE WHEN @cancel=1 THEN @amount ELSE -@amount END AND m.account_currency=N'TRY' AND m.account_amount=@amount AND m.amount_try=@amount AND m.document_exchange_rate_snapshot=1 AND m.account_exchange_rate_snapshot=1 AND m.created_by=@actor) ${deny}
 IF @customer=0 AND NOT EXISTS(SELECT 1 FROM dbo.supplier_movements m WHERE m.id=@movement AND m.supplier_id=2 AND m.purchase_invoice_id=5 AND m.movement_type=@kind AND m.amount=@amount AND m.balance_effect=CASE WHEN @cancel=1 THEN @amount ELSE -@amount END AND m.account_currency=N'TRY' AND m.account_amount=@amount AND m.amount_try=@amount AND m.document_exchange_rate_snapshot=1 AND m.account_exchange_rate_snapshot=1 AND m.created_by=@actor) ${deny}
 IF @customer=0 AND @cancel=1 AND(TRY_CONVERT(bigint,JSON_VALUE(@response,'$.payment.originalId'))<>@original OR JSON_VALUE(@response,'$.payment.kind')<>N'payment_cancel') ${deny}
 EXEC dbo.usp_clean_finance_b4_ready @verify_balances=1;DELETE dbo.${intent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();${witness('verified')} END;`;}

export function buildCleanFinanceRehearsalSql({probe=false,checkerPasswordHash}={}){
 if(typeof checkerPasswordHash!=='string'||!/^\$2[ab]\$12\$[./A-Za-z0-9]{53}$/.test(checkerPasswordHash))throw Error('B4 dedicated TEST checker bcrypt hash required');
 const {definitions,before}=buildCleanFinanceRehearsalDefinitions();
 return `SET QUOTED_IDENTIFIER ON;SET ANSI_NULLS ON;SET XACT_ABORT ON;SET NOCOUNT ON;${CLEAN_TARGET_SQL}
 IF ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 ${deny}
 IF OBJECT_ID(N'dbo.${manifest}') IS NOT NULL BEGIN EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_ready @verify_balances=1;SELECT N'B4_ALREADY_INSTALLED' status;RETURN;END;
 EXEC dbo.usp_clean_store_day_ready;
 BEGIN TRY BEGIN TRANSACTION;
 DECLARE @lock int;EXEC @lock=sys.sp_getapplock @Resource=N'CLEAN_STORE_DAY_20261022',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=5000;IF @lock<0 THROW 51962,'CLEAN_INBOUND_BUSY',1;
 ${Object.entries(before).map(([n,b])=>`IF ISNULL(CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.${n}'))),2),N'')<>${quote(moduleHash(b))} ${deny}`).join('\n')}
 IF EXISTS(SELECT 1 FROM dbo.clean_store_day_intents) OR EXISTS(SELECT 1 FROM dbo.clean_store_inventory_intents) OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_intents) OR EXISTS(SELECT 1 FROM dbo.work_trade_intents) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.customers WHERE id<>1) OR EXISTS(SELECT 1 FROM dbo.suppliers WHERE id<>1) OR EXISTS(SELECT 1 FROM dbo.finance_accounts WHERE id<>1) OR EXISTS(SELECT 1 FROM dbo.sales_invoices WHERE id<>1) OR EXISTS(SELECT 1 FROM dbo.purchase_invoices WHERE id=5) ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=10018 AND u.username=N'semih' AND r.id=28 AND r.code=N'clean_test_administrator' AND u.is_active=1) ${deny}
 DECLARE @beforeChecks nvarchar(max)=${checks},@stockHash varbinary(32)=HASHBYTES('SHA2_256',(SELECT id,current_stock_qty,average_cost_try FROM dbo.products ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES)),@stockCount bigint=(SELECT COUNT(*) FROM dbo.stock_movements),@oldCustomer nvarchar(max)=(SELECT * FROM dbo.customers WHERE id=1 FOR JSON PATH,INCLUDE_NULL_VALUES),@oldSupplier nvarchar(max)=(SELECT * FROM dbo.suppliers WHERE id=1 FOR JSON PATH,INCLUDE_NULL_VALUES),@oldCash nvarchar(max)=(SELECT * FROM dbo.finance_accounts WHERE id=1 FOR JSON PATH,INCLUDE_NULL_VALUES);
 CREATE TABLE dbo.${manifest}(name sysname PRIMARY KEY,before_hash char(64) NULL,after_hash char(64) NOT NULL,before_definition nvarchar(max) NULL,before_constraints_json nvarchar(max) NULL,after_constraints_hash char(64) NULL);
 CREATE TABLE dbo.${intent}(session_id int PRIMARY KEY,transaction_id bigint NOT NULL,request_id uniqueidentifier NOT NULL UNIQUE,actor_id bigint NOT NULL,operation nvarchar(40) NOT NULL,payload_hash char(64) NOT NULL,payload_json nvarchar(max) NOT NULL,amount decimal(18,4) NULL,original_id bigint NULL,account_before decimal(18,4) NULL,customer_before decimal(18,4) NULL,supplier_before decimal(18,4) NULL,customer_count_before bigint NULL,supplier_count_before bigint NULL,finance_count_before bigint NULL,customer_max_before bigint NULL,supplier_max_before bigint NULL,stock_count_before bigint NULL,stock_hash_before varbinary(32) NULL);
 CREATE TABLE dbo.${fixture}(id int PRIMARY KEY CHECK(id=1),case_id nvarchar(40) NOT NULL UNIQUE,customer_id bigint NOT NULL,supplier_id bigint NOT NULL,account_id bigint NOT NULL,sales_invoice_id bigint NOT NULL,purchase_invoice_id bigint NOT NULL,customer_movement_id bigint NOT NULL,supplier_movement_id bigint NOT NULL,currency nvarchar(3) NOT NULL CHECK(currency=N'TRY'),operation_date date NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),created_by bigint NOT NULL,setup_login nvarchar(128) NOT NULL);
 IF EXISTS(SELECT 1 FROM dbo.users WHERE id=23 OR username=N'ornek-finans-kontrol') OR EXISTS(SELECT 1 FROM dbo.roles WHERE id=29 OR code=N'clean_test_finance_checker') ${deny}
 SET IDENTITY_INSERT dbo.roles ON;INSERT dbo.roles(id,code,name)VALUES(29,N'clean_test_finance_checker',N'Örnek finans kontrolü');SET IDENTITY_INSERT dbo.roles OFF;
 SET IDENTITY_INSERT dbo.users ON;INSERT dbo.users(id,username,password_hash,display_name,role_id,is_active)VALUES(23,N'ornek-finans-kontrol',${quote(checkerPasswordHash)},N'Örnek finans kontrolü',29,1);SET IDENTITY_INSERT dbo.users OFF;
 ${['finance.view','customer.view','supplier.view'].map(k=>`INSERT dbo.permissions(role_id,permission_key,can_view,can_create,can_update,can_delete,can_approve)VALUES(29,${quote(k)},1,0,0,0,0);`).join('\n')}
 ${['finance.collection.cancel','finance.payment.cancel'].map(k=>`INSERT dbo.permissions(role_id,permission_key,can_view,can_create,can_update,can_delete,can_approve)VALUES(29,${quote(k)},1,1,0,0,0);`).join('\n')}
 ALTER TABLE dbo.customer_movements DROP CONSTRAINT CK_customer_movements_type;
 ALTER TABLE dbo.customer_movements WITH CHECK ADD CONSTRAINT CK_customer_movements_type CHECK(movement_type IN(N'sales_invoice',N'collection',N'collection_cancel'));
 ALTER TABLE dbo.supplier_movements DROP CONSTRAINT CK_supplier_movements_type;
 ALTER TABLE dbo.supplier_movements WITH CHECK ADD CONSTRAINT CK_supplier_movements_type CHECK(movement_type IN(N'purchase_invoice',N'payment',N'payment_cancel',N'purchase_return',N'purchase_return_cancel'));
 ALTER TABLE dbo.work_trade_requests DROP CONSTRAINT CK_clean_inventory_requests;
 ALTER TABLE dbo.work_trade_requests WITH CHECK ADD CONSTRAINT CK_clean_inventory_requests CHECK((actor_id IN(20,10018) AND operation IN(N'collection_create',N'payment'))OR(actor_id=23 AND operation IN(N'collection_cancel',N'payment_cancel'))OR(actor_id IN(21,10018) AND operation IN(N'stock_count_draft',N'purchase_return_draft'))OR(actor_id IN(22,10018) AND operation IN(N'stock_count_approve',N'stock_count_reject',N'stock_count_cancel',N'purchase_return_approve',N'purchase_return_reject',N'purchase_return_cancel')));
 ${Object.entries(definitions).filter(([n])=>!n.endsWith('_immutable')).map(([n,b])=>`EXEC(${quote(b.replace(/^CREATE PROCEDURE/,before[n]?'ALTER PROCEDURE':'CREATE PROCEDURE').replace(/^CREATE TRIGGER/,before[n]?'ALTER TRIGGER':'CREATE TRIGGER'))});`).join('\n')}
 ${Object.entries(definitions).map(([n,b])=>`INSERT dbo.${manifest}(name,before_hash,after_hash,before_definition,before_constraints_json,after_constraints_hash)VALUES(${quote(n)},${before[n]?quote(moduleHash(before[n])):'NULL'},${quote(moduleHash(b))},${before[n]?quote(before[n]):'NULL'},${n==='usp_clean_store_day_ready'?'@beforeChecks':'NULL'},${n==='usp_clean_store_day_ready'?"CONVERT(char(64),HASHBYTES('SHA2_256',"+checks+'),2)':'NULL'});`).join('\n')}
 ${Object.entries(definitions).filter(([n])=>n.endsWith('_immutable')).map(([,b])=>`EXEC(${quote(b)});`).join('\n')}
 DENY INSERT,UPDATE,DELETE ON dbo.${manifest} TO [${CLEAN_LOGIN}];DENY INSERT,UPDATE,DELETE ON dbo.${intent} TO [${CLEAN_LOGIN}];DENY INSERT,UPDATE,DELETE ON dbo.${fixture} TO [${CLEAN_LOGIN}];
 GRANT SELECT ON dbo.${fixture} TO [${CLEAN_LOGIN}];GRANT EXECUTE ON dbo.usp_clean_finance_b4_ready TO [${CLEAN_LOGIN}];GRANT EXECUTE ON dbo.usp_clean_finance_b4_bind TO [${CLEAN_LOGIN}];GRANT EXECUTE ON dbo.usp_clean_finance_b4_finish TO [${CLEAN_LOGIN}];
 INSERT dbo.${intent}(session_id,transaction_id,request_id,actor_id,operation,payload_hash,payload_json)VALUES(@@SPID,CURRENT_TRANSACTION_ID(),NEWID(),10018,N'fixture_prepare',REPLICATE('0',64),N'{"case":"B4-TRY-20261023","synthetic":true,"stockEffect":false}');
 ${fixtureDataSql()}
 DELETE dbo.${intent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();
 IF @stockHash<>HASHBYTES('SHA2_256',(SELECT id,current_stock_qty,average_cost_try FROM dbo.products ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES)) OR @stockCount<>(SELECT COUNT(*) FROM dbo.stock_movements) OR @oldCustomer COLLATE Latin1_General_100_BIN2<>(SELECT * FROM dbo.customers WHERE id=1 FOR JSON PATH,INCLUDE_NULL_VALUES) COLLATE Latin1_General_100_BIN2 OR @oldSupplier COLLATE Latin1_General_100_BIN2<>(SELECT * FROM dbo.suppliers WHERE id=1 FOR JSON PATH,INCLUDE_NULL_VALUES) COLLATE Latin1_General_100_BIN2 OR @oldCash COLLATE Latin1_General_100_BIN2<>(SELECT * FROM dbo.finance_accounts WHERE id=1 FOR JSON PATH,INCLUDE_NULL_VALUES) COLLATE Latin1_General_100_BIN2 ${deny}
 EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_ready @verify_balances=1;
 ${probe?"ROLLBACK;SELECT N'B4_FIXTURE_PROBE_ROLLED_BACK' status;":"COMMIT;SELECT N'B4_FIXTURE_INSTALLED' status;"}
 END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH;`;
}

