// The existing native daily-cash engine needs its own finite admission in this
// clean installation. This companion retains every predecessor body and hash.
const cashManifest='clean_finance_b4_cash_manifest',cashIntent='clean_finance_b4_cash_intents';
const cashAccounts=[{id:2,currency:'TRY',code:'B4-ORNEK-TRY',opening:0},{id:3,currency:'USD',code:'B4-ORNEK-USD',opening:0},{id:4,currency:'EUR',code:'B4-ORNEK-EUR',opening:0},{id:5,currency:'TRY',code:'KASA-TRY',opening:1000},{id:6,currency:'USD',code:'KASA-USD',opening:1000},{id:7,currency:'EUR',code:'KASA-EUR',opening:1000}];
const cashTables=['cash_drawers','cash_drawer_accounts','cash_sessions','cash_session_counts','expense_categories','cash_expenses','cash_transfers','cash_adjustments'];
const cashTableNames=cashTables.map(quote).join(',');
const cashSchema=`(SELECT JSON_QUERY((SELECT t.name table_name,c.column_id,c.name,TYPE_NAME(c.user_type_id) type_name,c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,d.definition default_definition FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id LEFT JOIN sys.default_constraints d ON d.object_id=c.default_object_id WHERE SCHEMA_NAME(t.schema_id)=N'dbo' AND t.name IN(${cashTableNames}) ORDER BY t.name,c.column_id FOR JSON PATH,INCLUDE_NULL_VALUES)) columns_json,JSON_QUERY((SELECT t.name table_name,c.name,c.definition,c.is_disabled,c.is_not_trusted FROM sys.tables t JOIN sys.check_constraints c ON c.parent_object_id=t.object_id WHERE SCHEMA_NAME(t.schema_id)=N'dbo' AND t.name IN(${cashTableNames}) ORDER BY t.name,c.name FOR JSON PATH,INCLUDE_NULL_VALUES)) checks_json,JSON_QUERY((SELECT t.name table_name,f.name,f.is_disabled,f.is_not_trusted,pc.name parent_column,OBJECT_NAME(f.referenced_object_id) referenced_table,rc.name referenced_column FROM sys.tables t JOIN sys.foreign_keys f ON f.parent_object_id=t.object_id JOIN sys.foreign_key_columns k ON k.constraint_object_id=f.object_id JOIN sys.columns pc ON pc.object_id=k.parent_object_id AND pc.column_id=k.parent_column_id JOIN sys.columns rc ON rc.object_id=k.referenced_object_id AND rc.column_id=k.referenced_column_id WHERE SCHEMA_NAME(t.schema_id)=N'dbo' AND t.name IN(${cashTableNames}) ORDER BY t.name,f.name,k.constraint_column_id FOR JSON PATH,INCLUDE_NULL_VALUES)) foreign_keys_json,JSON_QUERY((SELECT t.name table_name,i.name,i.is_unique,i.is_primary_key,i.is_disabled,i.filter_definition,k.key_ordinal,c.name column_name FROM sys.tables t JOIN sys.indexes i ON i.object_id=t.object_id JOIN sys.index_columns k ON k.object_id=i.object_id AND k.index_id=i.index_id JOIN sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE SCHEMA_NAME(t.schema_id)=N'dbo' AND t.name IN(${cashTableNames}) ORDER BY t.name,i.name,k.key_ordinal,k.index_column_id FOR JSON PATH,INCLUDE_NULL_VALUES)) indexes_json FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)`;
const cashRows=(table,where='')=>`JSON_QUERY((SELECT * FROM dbo.${table}${where} ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES))`;
const cashState=`(SELECT ${['finance_accounts','finance_account_movements','cash_sessions','cash_session_counts','cash_expenses','cash_transfers','cash_adjustments'].map(t=>`${cashRows(t,t==='finance_accounts'?' WHERE id BETWEEN 2 AND 7':t==='finance_account_movements'?' WHERE account_id BETWEEN 2 AND 7':'')} ${t}`).join(',')} FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)`;
const cashProtected=`(SELECT ${['products','product_prices','product_barcodes','stock_movements','customers','suppliers','customer_movements','supplier_movements','sales_invoices','sales_invoice_items','purchase_invoices','purchase_invoice_items'].map(t=>`${cashRows(t)} ${t}`).join(',')},${cashRows('finance_accounts',' WHERE id=1')} original_cash FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)`;
function cashLiftHashes(body){return body.replace(/CONVERT\(char\(64\),HASHBYTES\('SHA2_256',OBJECT_DEFINITION\(OBJECT_ID\(N'dbo\.'\+(\w+)\.name\)\)\),2\)/g,(hash,alias)=>`COALESCE((SELECT bc.before_hash FROM dbo.${cashManifest} bc WHERE bc.name=${alias}.name AND bc.after_hash=${hash}),${hash})`);}
function cashPrefix(body,table){const at=body.indexOf('AS BEGIN')+8;if(at<8)throw Error('B4 cash predecessor changed');const args=table?`N'${table}',(SELECT * FROM inserted FOR JSON PATH,INCLUDE_NULL_VALUES),(SELECT * FROM deleted FOR JSON PATH,INCLUDE_NULL_VALUES)`:'@table_name,@inserted,@deleted';return body.slice(0,at)+`\n IF EXISTS(SELECT 1 FROM dbo.${cashIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) BEGIN ${table?"DECLARE @ci nvarchar(max)=(SELECT * FROM inserted FOR JSON PATH,INCLUDE_NULL_VALUES),@cd nvarchar(max)=(SELECT * FROM deleted FOR JSON PATH,INCLUDE_NULL_VALUES);":''}EXEC dbo.usp_clean_finance_b4_cash_guard ${table?`N'${table}',@ci,@cd`:args};RETURN;END;\n`+body.slice(at);}
export function cleanFinanceCashSchemaSql(){
 const source=readFileSync(new URL('../../infra/sql/migrations/0012_multi_currency_cash_sessions.sql',import.meta.url),'utf8');
 return cashTables.map(table=>{const match=source.match(new RegExp(`  CREATE TABLE dbo\\.${table} \\([\\s\\S]*?^  \\);`,'m'));if(!match)throw Error('Existing cash schema missing '+table);return match[0];}).join('\n');
}
export function buildCleanFinanceCashSql({probe=false}={}){
 const {definitions,before}=buildCleanFinanceCashDefinitions();
 return `SET NOCOUNT ON;SET XACT_ABORT ON;${CLEAN_TARGET_SQL}
 IF ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 OR DB_NAME()<>N'MELISA_ERP_CLEAN_TEST_20261022' ${deny}
 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRANSACTION;BEGIN TRY
 DECLARE @lock int;EXEC @lock=sys.sp_getapplock @Resource=N'CLEAN_STORE_DAY_20261022',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=5000;IF @lock<0 ${deny}
 EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_ready @verify_balances=1;
 IF OBJECT_ID(N'dbo.${cashManifest}') IS NOT NULL OR OBJECT_ID(N'dbo.${cashIntent}') IS NOT NULL OR ${cashTables.map(t=>`OBJECT_ID(N'dbo.${t}') IS NOT NULL`).join(' OR ')} OR EXISTS(SELECT 1 FROM dbo.finance_accounts WHERE id BETWEEN 3 AND 7) OR EXISTS(SELECT 1 FROM dbo.clean_finance_b4_intents) OR EXISTS(SELECT 1 FROM dbo.clean_store_day_intents) OR EXISTS(SELECT 1 FROM dbo.clean_store_inventory_intents) OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_intents) ${deny}
 ${Object.entries(before).map(([name,body])=>`IF ISNULL(CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.${name}'))),2),N'')<>${quote(moduleHash(body))} ${deny}`).join('\n')}
 DECLARE @preserve varbinary(32)=HASHBYTES('SHA2_256',${cashProtected}),@oldAccount nvarchar(max)=(SELECT * FROM dbo.finance_accounts WHERE id=2 FOR JSON PATH,INCLUDE_NULL_VALUES),@oldRequests nvarchar(max)=(SELECT * FROM dbo.work_trade_requests ORDER BY request_id FOR JSON PATH,INCLUDE_NULL_VALUES),@beforeChecks nvarchar(max)=${checks};
 CREATE TABLE dbo.${cashManifest}(name sysname NOT NULL PRIMARY KEY,before_hash char(64) NULL,after_hash char(64) NOT NULL,before_definition nvarchar(max) NULL,before_constraints_json nvarchar(max) NULL,after_constraints_hash char(64) NULL,schema_hash char(64) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
 CREATE TABLE dbo.${cashIntent}(session_id int NOT NULL PRIMARY KEY,transaction_id bigint NOT NULL,request_id uniqueidentifier NOT NULL,actor_id bigint NOT NULL,operation nvarchar(40) NOT NULL,payload_hash char(64) NOT NULL,payload_json nvarchar(max) NOT NULL,before_counts nvarchar(max) NULL,before_balances nvarchar(max) NULL,protected_hash varbinary(32) NULL,cash_session_id bigint NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
 ${cleanFinanceCashSchemaSql()}
 DECLARE @constraint nvarchar(max)=(SELECT definition FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.work_trade_requests') AND name=N'CK_clean_inventory_requests');IF @constraint IS NULL ${deny}
 ALTER TABLE dbo.work_trade_requests DROP CONSTRAINT CK_clean_inventory_requests;
 EXEC(N'ALTER TABLE dbo.work_trade_requests WITH CHECK ADD CONSTRAINT CK_clean_inventory_requests CHECK(('+@constraint+N')OR(actor_id IN(20,10018) AND operation IN(N''cash_open'',N''cash_close'',N''cash_transfer'',N''cash_expense'')))');
 ${Object.entries(definitions).filter(([n])=>!n.endsWith('_immutable')).map(([name,body])=>`EXEC(${quote(body.replace(/^CREATE PROCEDURE/,before[name]?'ALTER PROCEDURE':'CREATE PROCEDURE').replace(/^CREATE TRIGGER/,before[name]?'ALTER TRIGGER':'CREATE TRIGGER'))});`).join('\n')}
 ${Object.entries(definitions).map(([name,body])=>`INSERT dbo.${cashManifest}(name,before_hash,after_hash,before_definition,before_constraints_json,after_constraints_hash,schema_hash)VALUES(${quote(name)},${before[name]?quote(moduleHash(before[name])):'NULL'},${quote(moduleHash(body))},${before[name]?quote(before[name]):'NULL'},${name==='usp_clean_store_day_ready'?'@beforeChecks':'NULL'},${name==='usp_clean_store_day_ready'?"CONVERT(char(64),HASHBYTES('SHA2_256',"+checks+'),2)':'NULL'},CONVERT(char(64),HASHBYTES('SHA2_256',${cashSchema}),2));`).join('\n')}
 ${Object.entries(definitions).filter(([n])=>n.endsWith('_immutable')).map(([,body])=>`EXEC(${quote(body)});`).join('\n')}
 DENY INSERT,UPDATE,DELETE ON dbo.${cashManifest} TO [${CLEAN_LOGIN}];DENY INSERT,UPDATE,DELETE ON dbo.${cashIntent} TO [${CLEAN_LOGIN}];
 GRANT EXECUTE ON dbo.usp_clean_finance_b4_cash_ready TO [${CLEAN_LOGIN}];GRANT EXECUTE ON dbo.usp_clean_finance_b4_cash_bind TO [${CLEAN_LOGIN}];GRANT EXECUTE ON dbo.usp_clean_finance_b4_cash_finish TO [${CLEAN_LOGIN}];
 ${cashTables.map(t=>`GRANT SELECT ON dbo.${t} TO [${CLEAN_LOGIN}];${['cash_sessions','cash_session_counts','cash_expenses','cash_transfers','cash_adjustments'].includes(t)?`GRANT INSERT ON dbo.${t} TO [${CLEAN_LOGIN}];`:`DENY INSERT ON dbo.${t} TO [${CLEAN_LOGIN}];`}${['cash_sessions','cash_session_counts'].includes(t)?`GRANT UPDATE ON dbo.${t} TO [${CLEAN_LOGIN}];`:`DENY UPDATE ON dbo.${t} TO [${CLEAN_LOGIN}];`}DENY DELETE ON dbo.${t} TO [${CLEAN_LOGIN}];`).join('\n')}
 INSERT dbo.${cashIntent}(session_id,transaction_id,request_id,actor_id,operation,payload_hash,payload_json)VALUES(@@SPID,CURRENT_TRANSACTION_ID(),NEWID(),10018,N'fixture_prepare',REPLICATE('0',64),N'{"case":"B4-CASH-20261023","synthetic":true,"stockEffect":false}');
 SET IDENTITY_INSERT dbo.finance_accounts ON;
 ${cashAccounts.filter(a=>a.id!==2).map(a=>`INSERT dbo.finance_accounts(id,account_code,account_name,account_type,currency_code,opening_balance,current_balance,is_active)VALUES(${a.id},N'${a.code}',N'Örnek ${a.currency} ${a.id<5?'günlük çekmece':'ana kasa'}',N'cash',N'${a.currency}',${a.opening},${a.opening},1);`).join('\n')}
 SET IDENTITY_INSERT dbo.finance_accounts OFF;
 SET IDENTITY_INSERT dbo.cash_drawers ON;INSERT dbo.cash_drawers(id,drawer_code,drawer_name,is_active)VALUES(1,N'B4-CEKMECE',N'Örnek günlük çekmece',1);SET IDENTITY_INSERT dbo.cash_drawers OFF;
 ${[['TRY',2],['USD',3],['EUR',4]].map(([c,id])=>`INSERT dbo.cash_drawer_accounts(drawer_id,currency_code,finance_account_id)VALUES(1,N'${c}',${id});`).join('\n')}
 SET IDENTITY_INSERT dbo.expense_categories ON;INSERT dbo.expense_categories(id,category_code,category_name,sort_order,is_active)VALUES(1,N'B4-ORNEK',N'Örnek günlük gider',1,1);SET IDENTITY_INSERT dbo.expense_categories OFF;
 DELETE dbo.${cashIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();
 IF @preserve<>HASHBYTES('SHA2_256',${cashProtected}) OR @oldAccount COLLATE Latin1_General_100_BIN2<>(SELECT * FROM dbo.finance_accounts WHERE id=2 FOR JSON PATH,INCLUDE_NULL_VALUES) COLLATE Latin1_General_100_BIN2 OR @oldRequests COLLATE Latin1_General_100_BIN2<>(SELECT * FROM dbo.work_trade_requests ORDER BY request_id FOR JSON PATH,INCLUDE_NULL_VALUES) COLLATE Latin1_General_100_BIN2 ${deny}
 EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_ready @verify_balances=1;EXEC dbo.usp_clean_finance_b4_cash_ready;
 ${probe?"ROLLBACK;SELECT N'B4_CASH_FIXTURE_PROBE_ROLLED_BACK' status;":"COMMIT;SELECT N'B4_CASH_FIXTURE_INSTALLED' status;"}
 END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;THROW;END CATCH;`;
}
export function buildCleanFinanceCashDefinitions(){
 const prior=buildCleanFinanceRehearsalDefinitions().definitions,definitions={};
 for(const name of ['usp_clean_store_day_ready','usp_clean_finance_b4_ready'])definitions[name]=cashLiftHashes(prior[name]);
 definitions.usp_clean_store_day_ready=definitions.usp_clean_store_day_ready.replace('(SELECT after_constraints_hash FROM dbo.clean_finance_b4_manifest',`(SELECT after_constraints_hash FROM dbo.${cashManifest}`);
 const end="AND a.opening_balance=0 AND a.is_active=1))";
 if(!definitions.usp_clean_store_day_ready.includes(end))throw Error('B4 cash account predecessor changed');
 definitions.usp_clean_store_day_ready=definitions.usp_clean_store_day_ready.replace(end,`AND a.opening_balance=0 AND a.is_active=1) AND NOT(a.id BETWEEN 3 AND 7))`);
 definitions.usp_clean_finance_b4_ready=definitions.usp_clean_finance_b4_ready.replace('\n END;','\n EXEC dbo.usp_clean_finance_b4_cash_ready;\n END;');
 definitions.usp_clean_store_finance_guard=cashPrefix(prior.usp_clean_store_finance_guard);
 definitions.clean_sale_audit_logs_guard=cashPrefix(prior.clean_sale_audit_logs_guard,'audit_logs');
 definitions.usp_clean_finance_b4_cash_ready=`CREATE PROCEDURE dbo.usp_clean_finance_b4_cash_ready @include_state bit=0 WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' AND ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 ${deny}
 IF(SELECT COUNT(*) FROM dbo.${cashManifest})<>/*CASH_COUNT*/ OR EXISTS(SELECT 1 FROM dbo.${cashManifest} m WHERE m.after_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name)) IS NULL OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'ExecIsTriggerDisabled')<>0)) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.${cashManifest} WHERE schema_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',${cashSchema}),2)) ${deny}
 ${cashAccounts.map(a=>`IF NOT EXISTS(SELECT 1 FROM dbo.finance_accounts WHERE id=${a.id} AND account_code=N'${a.code}' AND account_type=N'cash' AND currency_code=N'${a.currency}' AND opening_balance=${a.opening} AND is_active=1) ${deny}`).join('\n')}
 IF EXISTS(SELECT 1 FROM dbo.finance_accounts a WHERE a.id BETWEEN 2 AND 7 AND a.current_balance<>a.opening_balance+COALESCE((SELECT SUM(CASE WHEN f.direction=N'in' THEN f.amount ELSE -f.amount END) FROM dbo.finance_account_movements f WHERE f.account_id=a.id AND f.currency_code=a.currency_code),0)) ${deny}
 IF(SELECT COUNT(*) FROM dbo.cash_drawers)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.cash_drawers WHERE id=1 AND drawer_code=N'B4-CEKMECE' AND drawer_name=N'Örnek günlük çekmece' AND is_active=1) OR(SELECT COUNT(*) FROM dbo.cash_drawer_accounts)<>3 OR EXISTS(SELECT 1 FROM dbo.cash_drawer_accounts WHERE drawer_id<>1 OR finance_account_id<>CASE currency_code WHEN N'TRY' THEN 2 WHEN N'USD' THEN 3 WHEN N'EUR' THEN 4 ELSE -1 END) OR(SELECT COUNT(*) FROM dbo.expense_categories)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.expense_categories WHERE id=1 AND category_code=N'B4-ORNEK' AND category_name=N'Örnek günlük gider' AND is_active=1) OR(SELECT COUNT(*) FROM dbo.cash_sessions WHERE session_status=N'open')>1 ${deny}
 IF @include_state=1 SELECT LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',${cashState}),2)) revision,CONVERT(bit,1) verified,N'B4-CASH-20261023' profile;END;`;
 definitions.usp_clean_finance_b4_cash_bind=cashBindDefinition();
 definitions.usp_clean_finance_b4_cash_guard=cashGuardDefinition();
 definitions.usp_clean_finance_b4_cash_finish=cashFinishDefinition();
 for(const table of cashTables)definitions['clean_b4_'+table+'_guard']=`CREATE TRIGGER dbo.clean_b4_${table}_guard ON dbo.${table} WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON;DECLARE @i nvarchar(max)=(SELECT * FROM inserted FOR JSON PATH,INCLUDE_NULL_VALUES),@d nvarchar(max)=(SELECT * FROM deleted FOR JSON PATH,INCLUDE_NULL_VALUES);EXEC dbo.usp_clean_finance_b4_cash_guard N'${table}',@i,@d;END;`;
 definitions.clean_finance_b4_cash_manifest_immutable=`CREATE TRIGGER dbo.clean_finance_b4_cash_manifest_immutable ON dbo.${cashManifest} AFTER INSERT,UPDATE,DELETE AS BEGIN ${deny} END;`;
 const total=Object.keys(definitions).length;for(const name of Object.keys(definitions))definitions[name]=definitions[name].replaceAll('/*CASH_COUNT*/',String(total));
 return {definitions,before:Object.fromEntries(Object.keys(definitions).filter(n=>prior[n]).map(n=>[n,prior[n]])),total};
}

const cashCounts=`(SELECT (SELECT COUNT(*) FROM dbo.finance_account_movements) finance_count,(SELECT COALESCE(MAX(id),0) FROM dbo.finance_account_movements) finance_max,(SELECT COUNT(*) FROM dbo.cash_transfers) transfer_count,(SELECT COALESCE(MAX(id),0) FROM dbo.cash_transfers) transfer_max,(SELECT COUNT(*) FROM dbo.cash_adjustments) adjustment_count,(SELECT COALESCE(MAX(id),0) FROM dbo.cash_adjustments) adjustment_max,(SELECT COUNT(*) FROM dbo.cash_expenses) expense_count,(SELECT COALESCE(MAX(id),0) FROM dbo.cash_expenses) expense_max,(SELECT COUNT(*) FROM dbo.cash_sessions) session_count,(SELECT COALESCE(MAX(id),0) FROM dbo.cash_sessions) session_max,(SELECT COUNT(*) FROM dbo.cash_session_counts) count_count,(SELECT COUNT(*) FROM dbo.audit_logs) audit_count,(SELECT COUNT(*) FROM dbo.work_trade_requests) request_count FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)`;
const cashLoad=`DECLARE @op nvarchar(40),@actor bigint,@payload nvarchar(max),@request uniqueidentifier,@payloadHash char(64),@before nvarchar(max),@balances nvarchar(max),@sid bigint;SELECT @op=operation,@actor=actor_id,@payload=payload_json,@request=request_id,@payloadHash=payload_hash,@before=before_counts,@balances=before_balances,@sid=cash_session_id FROM dbo.${cashIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();IF @op IS NULL ${deny} IF @sid IS NULL AND @op=N'cash_open' SELECT @sid=id FROM dbo.cash_sessions WHERE drawer_id=1 AND business_date=CONVERT(date,'20261022',112);`;
function cashBindDefinition(){return `CREATE PROCEDURE dbo.usp_clean_finance_b4_cash_bind @actor_id bigint,@operation nvarchar(40),@request_id uniqueidentifier,@payload_hash char(64),@payload_json nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;${CLEAN_TARGET_SQL}
 EXEC dbo.usp_clean_store_day_ready;EXEC dbo.usp_clean_finance_b4_cash_ready;
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' OR @@TRANCOUNT<>1 OR ISNULL(APPLOCK_MODE(N'public',N'CLEAN_STORE_DAY_20261022',N'Transaction'),N'NoLock')<>N'Exclusive' OR EXISTS(SELECT 1 FROM dbo.${cashIntent} WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_finance_b4_intents WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_store_day_intents WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_store_inventory_intents WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_intents WHERE session_id=@@SPID) ${deny}
 DECLARE @permission nvarchar(80)=CASE WHEN @operation IN(N'cash_open',N'cash_close') THEN N'finance.collection' WHEN @operation IN(N'cash_transfer',N'cash_expense') THEN N'finance.payment' END;
 IF @request_id IS NULL OR @permission IS NULL OR ISJSON(@payload_json)<>1 OR @payload_hash IS NULL OR LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',@payload_json),2))<>LOWER(@payload_hash) OR ISNULL(JSON_VALUE(@payload_json,'$.actorId'),N'')<>CONVERT(nvarchar(20),@actor_id) OR ISNULL(JSON_VALUE(@payload_json,'$.operation'),N'')<>@operation OR ISNULL(LOWER(JSON_VALUE(@payload_json,'$.requestId')),N'')<>LOWER(CONVERT(nvarchar(36),@request_id)) OR EXISTS(SELECT 1 FROM dbo.work_trade_requests WHERE request_id=@request_id) ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id JOIN dbo.permissions p ON p.role_id=r.id WHERE u.id=@actor_id AND u.is_active=1 AND r.is_active=1 AND((u.id=20 AND u.username=N'ornek-finans' AND r.id=25 AND r.code=N'clean_test_finance')OR(u.id=10018 AND u.username=N'semih' AND r.id=28 AND r.code=N'clean_test_administrator')) AND(p.permission_key=@permission OR(@operation IN(N'cash_open',N'cash_close') AND p.permission_key=N'finance.payment')) AND p.can_create=1) ${deny}
 DECLARE @state nvarchar(max)=${cashState},@cashSession bigint=NULL;
 IF ISNULL(JSON_VALUE(@payload_json,'$.expectedRevision'),N'')<>LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',@state),2)) ${deny}
 IF EXISTS(SELECT 1 FROM OPENJSON(@payload_json) WHERE [key] NOT IN(N'actorId',N'operation',N'requestId',N'expectedRevision',N'drawerId',N'businessDate',N'openingNote',N'counts',N'sessionId',N'closingNote',N'currency',N'amount',N'direction',N'description',N'categoryId',N'documentNo')) ${deny}
 IF(SELECT COUNT(*) FROM OPENJSON(@payload_json))<>CASE @operation WHEN N'cash_open' THEN 8 WHEN N'cash_close' THEN 7 WHEN N'cash_transfer' THEN 9 ELSE 10 END OR(SELECT COUNT(*)-COUNT(DISTINCT [key]) FROM OPENJSON(@payload_json))<>0 OR EXISTS(SELECT 1 FROM OPENJSON(@payload_json) WHERE [key] NOT IN(N'actorId',N'operation',N'requestId',N'expectedRevision') AND NOT((@operation=N'cash_open' AND [key] IN(N'drawerId',N'businessDate',N'openingNote',N'counts'))OR(@operation=N'cash_close' AND [key] IN(N'sessionId',N'closingNote',N'counts'))OR(@operation=N'cash_transfer' AND [key] IN(N'sessionId',N'currency',N'amount',N'direction',N'description'))OR(@operation=N'cash_expense' AND [key] IN(N'sessionId',N'categoryId',N'currency',N'amount',N'description',N'documentNo')))) ${deny}
 IF @operation=N'cash_open' BEGIN IF ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.drawerId')),-1)<>1 OR ISNULL(JSON_VALUE(@payload_json,'$.businessDate'),N'')<>N'2026-10-22' OR EXISTS(SELECT 1 FROM dbo.cash_sessions WHERE session_status=N'open' OR(drawer_id=1 AND business_date=CONVERT(date,'20261022',112))) ${deny} END;
 ELSE BEGIN SET @cashSession=TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.sessionId'));IF @cashSession IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.cash_sessions WHERE id=@cashSession AND drawer_id=1 AND business_date=CONVERT(date,'20261022',112) AND session_status=N'open') ${deny} END;
 IF @operation IN(N'cash_open',N'cash_close') BEGIN
 IF(SELECT COUNT(*) FROM OPENJSON(@payload_json,'$.counts'))<>3 OR EXISTS(SELECT 1 FROM OPENJSON(@payload_json,'$.counts') c WHERE c.[key] NOT IN(N'TRY',N'USD',N'EUR') OR c.[type]<>5 OR(SELECT COUNT(*) FROM OPENJSON(c.value))<>2 OR EXISTS(SELECT 1 FROM OPENJSON(c.value) p WHERE p.[key] NOT IN(CASE WHEN @operation=N'cash_open' THEN N'physicalOpening' ELSE N'physicalClosing' END,CASE WHEN @operation=N'cash_open' THEN N'openingTransfer' ELSE N'carryForward' END) OR p.[type]<>2 OR TRY_CONVERT(decimal(28,8),p.value) IS NULL OR TRY_CONVERT(decimal(28,8),p.value) NOT BETWEEN 0 AND 10000 OR TRY_CONVERT(decimal(28,8),p.value)<>TRY_CONVERT(decimal(18,4),p.value))) ${deny}
 IF @operation=N'cash_close' AND EXISTS(SELECT 1 FROM OPENJSON(@payload_json,'$.counts') c WHERE TRY_CONVERT(decimal(18,4),JSON_VALUE(c.value,'$.carryForward'))>TRY_CONVERT(decimal(18,4),JSON_VALUE(c.value,'$.physicalClosing'))) ${deny}
 IF(SELECT COUNT(DISTINCT [key]) FROM OPENJSON(@payload_json,'$.counts'))<>3 OR EXISTS(SELECT 1 FROM OPENJSON(@payload_json,'$.counts') c WHERE(SELECT COUNT(DISTINCT [key]) FROM OPENJSON(c.value))<>2) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.finance_accounts a WHERE a.id IN(2,3,4) AND a.current_balance<>TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,N'$.counts.'+a.currency_code+CASE WHEN @operation=N'cash_open' THEN N'.physicalOpening' ELSE N'.physicalClosing' END))) AND LEN(LTRIM(RTRIM(ISNULL(JSON_VALUE(@payload_json,CASE WHEN @operation=N'cash_open' THEN '$.openingNote' ELSE '$.closingNote' END),N''))))<5 ${deny}
 END ELSE BEGIN
 DECLARE @currency nvarchar(3)=JSON_VALUE(@payload_json,'$.currency'),@amount decimal(18,4)=TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,'$.amount'));
 IF @currency NOT IN(N'TRY',N'USD',N'EUR') OR @currency IS NULL OR @amount IS NULL OR @amount<=0 OR @amount>500 OR @amount<>TRY_CONVERT(decimal(28,8),JSON_VALUE(@payload_json,'$.amount')) OR LEN(LTRIM(RTRIM(ISNULL(JSON_VALUE(@payload_json,'$.description'),N''))))<5 ${deny}
 IF @operation=N'cash_transfer' AND ISNULL(JSON_VALUE(@payload_json,'$.direction'),N'') NOT IN(N'main_to_drawer',N'drawer_to_main') ${deny}
 IF @operation=N'cash_expense' AND ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.categoryId')),-1)<>1 ${deny}
 END;
 INSERT dbo.${cashIntent}(session_id,transaction_id,request_id,actor_id,operation,payload_hash,payload_json,before_counts,before_balances,protected_hash,cash_session_id)
 SELECT @@SPID,CURRENT_TRANSACTION_ID(),@request_id,@actor_id,@operation,UPPER(@payload_hash),@payload_json,${cashCounts},(SELECT id,current_balance FROM dbo.finance_accounts WHERE id BETWEEN 2 AND 7 ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',${cashProtected}),@cashSession;
 DECLARE @actor bigint=@actor_id,@op nvarchar(40)=@operation,@hash char(64)=@payload_hash;${witness('accepted')} END;`;}

// Add only two finite synthetic currency cases to the installed native finance
// engine. Old TRY/cash manifests and their before-images remain immutable.
const fxManifest='clean_finance_b4_fx_manifest',fxIntent='clean_finance_b4_fx_intents',fxFixture='clean_finance_b4_fx_fixture';
function fxLiftHashes(body){
 return body.replace(/CONVERT\(char\(64\),HASHBYTES\('SHA2_256',OBJECT_DEFINITION\(OBJECT_ID\(N'dbo\.'\+(\w+)\.name\)\)\),2\)/g,(hash,alias)=>`COALESCE((SELECT bf.before_hash FROM dbo.${fxManifest} bf WHERE bf.name=${alias}.name AND bf.after_hash=${hash}),${hash})`);
}
function fxNativeBody(body,p,kind){
 if(p.customerId!==p.supplierId||p.customerId!==p.invoiceId||p.customerId!==p.accountId)throw Error('FX fixed identity contract changed');
 const rate=Number(p.rateExact8),prefix='usp_clean_finance_b4_fx_'+p.currency.toLowerCase();
 let out=body.replaceAll(`dbo.${intent}`,`dbo.${fxIntent}`).replaceAll('dbo.usp_clean_finance_b4_ready','dbo.usp_clean_finance_b4_fx_ready').replaceAll('dbo.usp_clean_finance_b4_'+kind,'dbo.'+prefix+'_'+kind).replaceAll("N'TRY'",quote(p.currency));
 for(const [key,id]of [['customer_id',p.customerId],['supplier_id',p.supplierId],['sales_invoice_id',p.invoiceId],['purchase_invoice_id',p.purchaseInvoiceId],['account_id',p.accountId],['invoice_id',p.invoiceId]])out=out.replace(new RegExp(`\\b${key}=${key==='purchase_invoice_id'?5:2}\\b`,'g'),`${key}=${id}`);
 out=out.replace(/\bWHERE id=2\b/g,'WHERE id='+p.customerId).replaceAll("<>N'2'",`<>N'${p.customerId}'`).replaceAll("<>N'5'",`<>N'${p.purchaseInvoiceId}'`).replaceAll('THEN 2 ELSE 5 END',`THEN ${p.invoiceId} ELSE ${p.purchaseInvoiceId} END`).replaceAll("N'_id')),-1)<>2",`N'_id')),-1)<>${p.customerId}`);
 for(const [key,id,old]of [['id',p.customerId,2],['id',p.purchaseInvoiceId,5],['customer_id',p.customerId,2],['supplier_id',p.supplierId,2],['sales_invoice_id',p.invoiceId,2],['purchase_invoice_id',p.purchaseInvoiceId,5],['account_id',p.accountId,2],['invoice_id',p.invoiceId,2]])out=out.replaceAll(`${N(key)}<>${old}`,`${N(key)}<>${id}`);
 out=out.replaceAll("N'B4-ORNEK-M'",quote(p.customerCode)).replaceAll("N'B4 Örnek Müşteri'",quote(p.customerName)).replaceAll("N'B4-ORNEK-T'",quote(p.supplierCode)).replaceAll("N'B4 Örnek Tedarikçi'",quote(p.supplierName)).replaceAll("N'B4-ORNEK-TRY'",quote('B4-ORNEK-'+p.currency)).replaceAll("N'B4-ORNEK-TAHSILAT'",quote(p.invoiceNumber)).replaceAll("N'B4-ORNEK-ODEME'",quote(p.purchaseNumber));
 for(const key of ['exchange_rate_snapshot','account_exchange_rate_snapshot','document_exchange_rate_snapshot'])out=out.replaceAll(`${N(key)}<>1`,`${N(key)}<>${rate}`);
 for(const field of ['document_exchange_rate_snapshot','account_exchange_rate_snapshot'])out=out.replaceAll(`m.${field}=1`,`m.${field}=${rate}`);
 out=out.replaceAll('m.amount=m.amount_try',`m.amount_try=CONVERT(decimal(18,4),m.amount*${rate})`).replaceAll('m.amount_try=@amount',`m.amount_try=CONVERT(decimal(18,4),@amount*${rate})`);
 out=out.replaceAll(`${N('amount_try')}<>@amount`,`${N('amount_try')}<>CONVERT(decimal(18,4),@amount*${rate})`).replaceAll(`${N('amount_try')}<>251`,`${N('amount_try')}<>${251*rate}`).replaceAll(`${N('amount_try')}<>200`,`${N('amount_try')}<>${200*rate}`).replaceAll(`${N('line_total_try')}<>200`,`${N('line_total_try')}<>${200*rate}`);
 if(kind==='bind'){
  out=out.replace('SET NOCOUNT ON;','SET NOCOUNT ON;'+`IF ISNULL(JSON_VALUE(@payload_json,'$.financeCaseId'),N'')<>${quote(p.id)} ${deny}`);
  const existing=`OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_intents WHERE session_id=@@SPID)`;
  if(!out.includes(existing))throw Error('FX binder predecessor changed');
  out=out.replace(existing,existing+` OR EXISTS(SELECT 1 FROM dbo.${intent} WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.${cashIntent} WHERE session_id=@@SPID)`);
 }else{
  const marker=`IF @op IS NULL ${deny}`;if(!out.includes(marker))throw Error('FX intent predecessor changed');
  out=out.replace(marker,marker+` IF ISNULL(JSON_VALUE(@payload,'$.financeCaseId'),N'')<>${quote(p.id)} ${deny}`);
 }
 if(kind==='guard')out=out.replace("IF @op=N'fixture_prepare' BEGIN","IF @op=N'fixture_prepare' BEGIN IF @table_name=N'finance_accounts' "+deny);
 return out;
}
function fxPrefix(body,table){
 const at=body.indexOf('AS BEGIN')+8;if(at<8)throw Error('FX guard predecessor changed');
 const declare=table?"DECLARE @b4fxInserted nvarchar(max)=(SELECT * FROM inserted FOR JSON PATH,INCLUDE_NULL_VALUES),@b4fxDeleted nvarchar(max)=(SELECT * FROM deleted FOR JSON PATH,INCLUDE_NULL_VALUES);":'';
 const args=table?`N'${table}',@b4fxInserted,@b4fxDeleted`:'@table_name,@inserted,@deleted';
 return body.slice(0,at)+`\n IF EXISTS(SELECT 1 FROM dbo.${fxIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) BEGIN ${declare}EXEC dbo.usp_clean_finance_b4_fx_guard ${args};RETURN;END;\n`+body.slice(at);
}
export function buildCleanFinanceFxDefinitions(){
 const b4=buildCleanFinanceRehearsalDefinitions().definitions,cash=buildCleanFinanceCashDefinitions().definitions,prior={...b4,...cash},definitions={};
 for(const name of ['usp_clean_store_day_ready','usp_clean_finance_b4_ready','usp_clean_finance_b4_cash_ready'])definitions[name]=fxLiftHashes(prior[name]);
 for(const [name,table]of [['clean_sale_customers_guard','customers'],['clean_sale_customer_movements_guard','customer_movements'],['clean_sale_sales_invoices_guard','sales_invoices'],['clean_sale_sales_invoice_items_guard','sales_invoice_items'],['clean_sale_audit_logs_guard','audit_logs'],['usp_clean_store_day_guard',null],['usp_clean_store_finance_guard',null]])definitions[name]=fxPrefix(prior[name],table);
 for(const p of CLEAN_FINANCE_FX_CASES)for(const kind of ['bind','guard','finish'])definitions['usp_clean_finance_b4_fx_'+p.currency.toLowerCase()+'_'+kind]=fxNativeBody(b4['usp_clean_finance_b4_'+kind],p,kind);
 definitions.usp_clean_finance_b4_fx_bind=`CREATE PROCEDURE dbo.usp_clean_finance_b4_fx_bind @actor_id bigint,@operation nvarchar(40),@request_id uniqueidentifier,@payload_hash char(64),@payload_json nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL} DECLARE @case nvarchar(40)=JSON_VALUE(@payload_json,'$.financeCaseId');${CLEAN_FINANCE_FX_CASES.map(p=>`IF @case=${quote(p.id)} BEGIN EXEC dbo.usp_clean_finance_b4_fx_${p.currency.toLowerCase()}_bind @actor_id,@operation,@request_id,@payload_hash,@payload_json;RETURN;END;`).join('')} ${deny} END;`;
 definitions.usp_clean_finance_b4_fx_finish=`CREATE PROCEDURE dbo.usp_clean_finance_b4_fx_finish @request_id uniqueidentifier WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL} DECLARE @case nvarchar(40)=(SELECT JSON_VALUE(payload_json,'$.financeCaseId') FROM dbo.${fxIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID() AND request_id=@request_id);${CLEAN_FINANCE_FX_CASES.map(p=>`IF @case=${quote(p.id)} BEGIN EXEC dbo.usp_clean_finance_b4_fx_${p.currency.toLowerCase()}_finish @request_id;RETURN;END;`).join('')} ${deny} END;`;
 definitions.usp_clean_finance_b4_fx_guard=`CREATE PROCEDURE dbo.usp_clean_finance_b4_fx_guard @table_name sysname,@inserted nvarchar(max),@deleted nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL} DECLARE @case nvarchar(40)=(SELECT JSON_VALUE(payload_json,'$.financeCaseId') FROM dbo.${fxIntent} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID());${CLEAN_FINANCE_FX_CASES.map(p=>`IF @case=${quote(p.id)} BEGIN EXEC dbo.usp_clean_finance_b4_fx_${p.currency.toLowerCase()}_guard @table_name,@inserted,@deleted;RETURN;END;`).join('')} ${deny} END;`;
 definitions.usp_clean_finance_b4_fx_ready=`CREATE PROCEDURE dbo.usp_clean_finance_b4_fx_ready @verify_balances bit=0 WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' AND ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 ${deny}
 IF(SELECT COUNT(*) FROM dbo.${fxManifest})<>/*FX_COUNT*/ OR EXISTS(SELECT 1 FROM dbo.${fxManifest} m WHERE m.after_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name)) IS NULL OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'ExecIsTriggerDisabled')<>0)) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.${fxManifest} f LEFT JOIN sys.sql_modules m ON m.object_id=OBJECT_ID(N'dbo.'+f.name) WHERE ISNULL(m.uses_quoted_identifier,0)<>1 OR ISNULL(m.uses_ansi_nulls,0)<>1) ${deny}
 IF(SELECT COUNT(*) FROM dbo.${fxFixture})<>2 ${deny}
 ${CLEAN_FINANCE_FX_CASES.map(p=>`IF NOT EXISTS(SELECT 1 FROM dbo.${fxFixture} f JOIN dbo.customers c ON c.id=f.customer_id JOIN dbo.suppliers s ON s.id=f.supplier_id JOIN dbo.finance_accounts a ON a.id=f.account_id JOIN dbo.sales_invoices i ON i.id=f.sales_invoice_id JOIN dbo.purchase_invoices pi ON pi.id=f.purchase_invoice_id WHERE f.id=${p.fxFixtureId} AND f.case_id=${quote(p.id)} AND f.customer_id=${p.customerId} AND f.supplier_id=${p.supplierId} AND f.account_id=${p.accountId} AND f.sales_invoice_id=${p.invoiceId} AND f.purchase_invoice_id=${p.purchaseInvoiceId} AND f.currency=${quote(p.currency)} AND f.synthetic_rate=${Number(p.rateExact8)} AND f.operation_date=CONVERT(date,'20261022',112) AND c.customer_code=${quote(p.customerCode)} AND c.name=${quote(p.customerName)} AND c.currency_code=f.currency AND c.is_active=1 AND c.is_deleted=0 AND s.supplier_code=${quote(p.supplierCode)} AND s.name=${quote(p.supplierName)} AND s.currency_code=f.currency AND s.is_active=1 AND s.is_deleted=0 AND a.account_code=N'B4-ORNEK-${p.currency}' AND a.currency_code=f.currency AND a.account_type=N'cash' AND a.opening_balance=0 AND a.is_active=1 AND i.customer_id=c.id AND i.document_no=${quote(p.invoiceNumber)} AND i.status=N'finalized' AND i.document_currency=f.currency AND i.grand_total=251 AND i.account_amount=251 AND i.account_currency=f.currency AND i.exchange_rate_snapshot=f.synthetic_rate AND i.account_exchange_rate_snapshot=f.synthetic_rate AND i.amount_try=251*f.synthetic_rate AND pi.supplier_id=s.id AND pi.document_no=${quote(p.purchaseNumber)} AND pi.status=N'finalized' AND pi.document_currency=f.currency AND pi.grand_total=200 AND pi.account_amount=200 AND pi.account_currency=f.currency AND pi.exchange_rate_snapshot=f.synthetic_rate AND pi.account_exchange_rate_snapshot=f.synthetic_rate AND pi.amount_try=200*f.synthetic_rate) ${deny}
 IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds WHERE(entity=N'customer' AND native_id=${p.customerId})OR(entity=N'supplier' AND native_id=${p.supplierId})OR(entity=N'product' AND native_id=1)) ${deny}
 IF @verify_balances=1 AND(NOT EXISTS(SELECT 1 FROM dbo.customers c WHERE id=${p.customerId} AND balance=(SELECT COALESCE(SUM(balance_effect),0) FROM dbo.customer_movements WHERE customer_id=c.id AND currency_code=${quote(p.currency)}))OR NOT EXISTS(SELECT 1 FROM dbo.suppliers s WHERE id=${p.supplierId} AND balance=(SELECT COALESCE(SUM(balance_effect),0) FROM dbo.supplier_movements WHERE supplier_id=s.id AND currency_code=${quote(p.currency)}))OR NOT EXISTS(SELECT 1 FROM dbo.finance_accounts a WHERE id=${p.accountId} AND current_balance=(SELECT COALESCE(SUM(CASE WHEN direction=N'in' THEN amount ELSE -amount END),0) FROM dbo.finance_account_movements WHERE account_id=a.id AND currency_code=${quote(p.currency)}))) ${deny}`).join('\n')}
 END;`;
 definitions.clean_finance_b4_fx_manifest_immutable=`CREATE TRIGGER dbo.clean_finance_b4_fx_manifest_immutable ON dbo.${fxManifest} AFTER INSERT,UPDATE,DELETE AS BEGIN ${deny} END;`;
 definitions.clean_finance_b4_fx_fixture_immutable=`CREATE TRIGGER dbo.clean_finance_b4_fx_fixture_immutable ON dbo.${fxFixture} AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON;IF EXISTS(SELECT 1 FROM deleted) OR(SELECT COUNT(*) FROM inserted)<>1 OR ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.${fxIntent} t JOIN inserted i ON JSON_VALUE(t.payload_json,'$.financeCaseId')=i.case_id WHERE t.session_id=@@SPID AND t.transaction_id=CURRENT_TRANSACTION_ID() AND t.operation=N'fixture_prepare') ${deny} END;`;
 const total=Object.keys(definitions).length;for(const name of Object.keys(definitions))definitions[name]=definitions[name].replaceAll('/*FX_COUNT*/',String(total));
 return {definitions,before:Object.fromEntries(Object.keys(definitions).filter(n=>prior[n]).map(n=>[n,prior[n]])),total};
}

